const TAROT=[{"n":0,"name":"愚者","img":"00_Fool.jpg","intro":"愚者常与开放、好奇以及踏入陌生领域的第一步相关。它并不保证每次尝试都会顺利，而是邀请你在面对可能性时，同时带上勇气与觉察。","love":{"h":"新的关系或联结","t":"保持开放不等于放弃边界。留意哪些判断来自彼此实际的行动，哪些仍是自己的猜测，以及什么对话能让下一步更清晰。"},"study":{"h":"抽到逆位时","t":"同一个主题可能表现为犹豫，也可能表现为急于向前。想想有哪些现实细节需要先确认，再选择一个方便调整的步骤。"},"career":{"h":"开始一个项目","t":"让好奇心变成一个规模小、可以调整的尝试。先说清楚你想了解什么，检查可投入的时间或预算，并想好哪些迹象会帮助你决定是否继续。"},"wealth":{"h":"综合提示","t":"愚者常与开放、好奇以及踏入陌生领域的第一步相关。它并不保证每次尝试都会顺利，而是邀请你在面对可能性时，同时带上勇气与觉察。"},"next":"写下一件你想尝试的事，再写下一项能让自己更安心的准备。你不必在出发前就决定整段旅程的方向。"},{"n":1,"name":"魔术师","img":"01_Magician.jpg","intro":"魔术师常与自主行动、技巧和有意识的专注联系在一起。它并不意味着只要有愿望就能左右结果，而是可以帮助你看见自己已掌握的能力、手边可用的资源，以及哪些投入可能带来切实进展。","love":{"h":"一场关系中的对话","t":"想想怎样让谈话更清楚、更有建设性。先确定自己想表达的重点，选一个平静的时机，也给对方回应的空间。把注意力放在自己能如何沟通，而不是试图控制谈话结果。"},"study":{"h":"工作或学习","t":"挑一件能用现有技能推进的任务，明确怎样才算完成，备好所需材料，再安排一段短时间开始。先完成一个小步骤，可以帮助你判断当前的方法是否有效。"},"career":{"h":"抽到逆位时","t":"如果好几个计划都在争夺注意力，先别急着再添一个。列出手头正在做的事，圈出本周最重要的一项，再决定哪些可以延后。这样能把分散的力气收拢到一件真正能继续推进的事上。"},"wealth":{"h":"综合提示","t":"魔术师常与自主行动、技巧和有意识的专注联系在一起。它并不意味着只要有愿望就能左右结果，而是可以帮助你看见自己已掌握的能力、手边可用的资源，以及哪些投入可能带来切实进展。"},"next":"在纸上写下一个具体目标，再列出一项可用的技能、一种现有资源，以及一个能在二十分钟内完成的最小行动。先做完这一步，再考虑是否要调整整个计划。"},{"n":2,"name":"女祭司","img":"02_High_Priestess.jpg","intro":"女祭司常与静心、保留以及尚未明朗的事物相关。这张牌可以邀请你留意内心的感受，但不必把它当成事实。给自己一点时间，分辨当下的感受、已经掌握的信息，以及仍需沟通或查证的部分。","love":{"h":"面对感情问题","t":"如果一段对话让你觉得意犹未尽，记下具体哪些言语或行为使你感到不确定，再把观察到的事和自己的解读分开。想想有什么可以直接询问。内心的感受值得留意，但不代表你已经知道对方在想什么。"},"study":{"h":"工作或学习中","t":"如果一个选择还不清楚，可以先花时间核对细节，再决定是否继续。分辨哪些部分自己已经弄懂，哪些需要向同事、老师或可靠的信息来源确认。稍作停顿，有助于提出更有用的问题，而不是只靠猜测。"},"career":{"h":"感到想要退缩时","t":"试着分辨自己是需要独处，还是正在回避一段对自己重要的联系。说清楚让你不舒服的地方，再选择一种压力较小的方式联系对方或表达需要空间。留意反复出现、可以观察到的线索，不要只凭恐惧下判断。"},"wealth":{"h":"综合提示","t":"女祭司常与静心、保留以及尚未明朗的事物相关。这张牌可以邀请你留意内心的感受，但不必把它当成事实。给自己一点时间，分辨当下的感受、已经掌握的信息，以及仍需沟通或查证的部分。"},"next":"安静五分钟，记下最先浮现的想法，再写下一条支持它的事实，以及一件仍需确认的事。结合两者，选一个小小的下一步。"},{"n":3,"name":"皇后","img":"03_Empress.jpg","intro":"皇后常与关怀、创造力，以及让生活得到滋养的条件有关。这张牌并不是要你不断付出，而是邀请你留意什么能支撑自己的精力、什么带来真实的愉悦，以及接受帮助是否也和给予帮助一样重要。","love":{"h":"关系中的关怀","t":"留意日常相处中，关怀如何给予与接收。你可以说出一件让自己感到被支持的小事，也可以看看自己付出的时间或精力，是否已经超过能够轻松承担的范围。"},"study":{"h":"关怀似乎不对等时","t":"答应新的请求之前先停一停。想清楚自己能提供什么而不感到怨怼、哪些事情可以稍后处理，并在日程中留出一项恢复精力的活动。清楚的限度能让关怀更持久。"},"career":{"h":"培育一个创意项目","t":"为想法安排一个实际的发展空间。固定留出一段时间，准备好所需材料，也允许第一版并不完美。留意哪些部分让你有活力，哪些部分需要更简单的做法。"},"wealth":{"h":"综合提示","t":"皇后常与关怀、创造力，以及让生活得到滋养的条件有关。这张牌并不是要你不断付出，而是邀请你留意什么能支撑自己的精力、什么带来真实的愉悦，以及接受帮助是否也和给予帮助一样重要。"},"next":"今天为自己选一件小小的照料之事，例如好好吃一顿饭、散步片刻，或留二十分钟做点创作。把它写进日程，之后留意自己的感受。"},{"n":4,"name":"皇帝","img":"04_Emperor.jpg","intro":"皇帝牌常与秩序、责任以及权威如何运用有关。它并不是要求你事事掌控，而是可以帮助你看清哪些界限有助于守住优先事项，以及哪些时候合作和调整会更有效。","love":{"h":"感情或关系问题","t":"留意一项约定是否让双方的日常相处更清楚。坦率说出一条界限或期待，再听听对方的看法。好的规则应当帮助彼此协调，而不是取代倾听，或变成控制他人的方式。"},"study":{"h":"工作或学习","t":"找出哪项责任需要明确归属。写下目标、每部分由谁负责，以及何时检查进度。如果你承担带领职责，也可以了解他人需要什么支持；保持可靠并不等于所有事都亲自包办。"},"career":{"h":"抽到逆位时","t":"检查某条规则是否真的解决了原本要处理的问题。想想它服务于谁的需要、带来了什么代价，以及能否通过小幅调整，在保障基本需要的同时留出表达和成长的空间。"},"wealth":{"h":"综合提示","t":"皇帝牌常与秩序、责任以及权威如何运用有关。它并不是要求你事事掌控，而是可以帮助你看清哪些界限有助于守住优先事项，以及哪些时候合作和调整会更有效。"},"next":"选一个期待尚不明确的方面，写下一份简单约定，包括重要事项、每个人或每项任务的需要，以及何时重新讨论。尽量写得具体可用，同时保留调整的余地。"},{"n":5,"name":"教皇","img":"05_Hierophant.jpg","intro":"教皇常与通过共同习俗、老师和社群获得的学习有关。这张牌可以让你留意哪些关系与制度带来了联结，同时也给你空间判断它们是否仍然适合自己。你可以借此思考，哪些东西想继续传承，哪些又可以重新理解。","love":{"h":"家庭或社群传统","t":"选一项对家庭或社群有意义的习俗，想想它带来了什么：联结、延续感，还是共同的意义。也留意自己是否出于自愿参与。如果它已不再适合，想想能否调整做法，同时保留你珍视的部分。"},"study":{"h":"向导师学习","t":"留意老师的建议中，哪些部分有经验或清晰的理由作为支撑。写下自己想学什么，再请对方举例或让你实际练习。你可以尊重对方的专业，同时判断这些指导如何适用于自己的处境。"},"career":{"h":"抽到逆位时","t":"如果某条规则或群体期待让你不舒服，先找出具体令你介意的部分，不必立刻全盘否定。了解这项做法最初的缘由，再对照自己现在的价值观，想想什么样的界限或沟通会有帮助。"},"wealth":{"h":"综合提示","t":"教皇常与通过共同习俗、老师和社群获得的学习有关。这张牌可以让你留意哪些关系与制度带来了联结，同时也给你空间判断它们是否仍然适合自己。你可以借此思考，哪些东西想继续传承，哪些又可以重"},"next":"写下一项你正在参与的传统或共同习俗，再记下它带给你的东西、让你为难的地方，以及一种由自己选择继续、调整或暂时退出的方式。"},{"n":6,"name":"恋人","img":"06_Lovers.jpg","intro":"恋人牌与联结、共同价值观以及需要坦诚面对的选择有关。在感情问题中，它可以邀请你思考双方如何相处，但无法证实对方的心意，也不保证关系会走向某种结果。","love":{"h":"感情问题","t":"留意双方说过的话与实际行动是否相互回应。如果有重要问题尚不明确，直接沟通比把牌面当成对方真实想法的证据更可靠。"},"study":{"h":"权衡一个选择","t":"写下这项决定涉及的价值观，以及每个选项需要承担的取舍。值得思考的也许是哪个选择更符合自己的原则，而不是哪个能保证完美结果。"},"career":{"h":"抽到逆位时","t":"留意回避、不对等的投入，或想要的生活与正在做的选择之间是否不一致。试着分清自己的偏好与取悦他人、证明自己的压力。"},"wealth":{"h":"综合提示","t":"恋人牌与联结、共同价值观以及需要坦诚面对的选择有关。在感情问题中，它可以邀请你思考双方如何相处，但无法证实对方的心意，也不保证关系会走向某种结果。"},"next":"说出一项你想坚持的价值观，再找出一个有助于你据此行动的坦诚问题或对话。"},{"n":7,"name":"战车","img":"07_Chariot.jpg","intro":"战车常被解读为方向感与有目标的行动。当几件事同时牵扯你的精力时，它可以提醒你留意是什么在引导自己的步调。不要把持续前进当成必须继续的证明，不妨借这张牌看看，下一步是否契合你真正重视的事。","love":{"h":"平衡多项责任","t":"几项责任同时拉扯你时，写下本周每件事需要你做什么。看看时间已经花在哪里，再决定哪些事可以延期、分担或婉拒。设下清楚的界限，或许能帮助你更有意识地分配精力。"},"study":{"h":"觉得进展不顺时","t":"如果觉得自己是在勉强推进，可以停下来想想：忙个不停，是为了证明什么，或是为了避开什么？检查自己的精力和目标背后的理由。你可以调整时间安排，或先走一小步，不必要求自己马上全速前进。"},"career":{"h":"赶工作期限","t":"面对截止日期，列出真正推动工作完成的任务，以及只是制造紧迫感的事情。为接下来的一段工作时间选定一个重点，说明怎样才算完成，并检查安排是否留有保证质量和休息的空间。"},"wealth":{"h":"综合提示","t":"战车常被解读为方向感与有目标的行动。当几件事同时牵扯你的精力时，它可以提醒你留意是什么在引导自己的步调。不要把持续前进当成必须继续的证明，不妨借这张牌看看，下一步是否契合你真正重视"},"next":"设定五分钟计时，写下一个主要目标、接下来能采取的行动，以及暂时可以放到一旁的一项干扰或要求。选一个今天剩余时间里也能维持的步调。"},{"n":8,"name":"力量","img":"08_Strength.jpg","intro":"力量牌常被理解为一种沉稳回应的练习：面对强烈情绪或困难处境时，不让一时的急迫替你决定下一步。它并不是要你压抑愤怒或忍受伤害，而是邀请你留意什么需要照顾、哪里需要设下界限，以及怎样的回应符合自己的价值观。","love":{"h":"关系中的意见不合","t":"留意自己是否忙着准备回应，而没有听清对方在说什么。先短暂停顿，说明你希望对方理解的重点，再想想什么界限或请求能让对话更尊重彼此。耐心不代表必须认同，也不代表要接受伤害性的对待。"},"study":{"h":"工作或学习遇到难题","t":"有挑战的任务可能考验你的精力和专注力。把工作拆成一个明确的下一步，并在不断增加任务前先界定什么算完成。如果反馈听起来刺耳，试着把有用的信息和表达语气分开，再决定一项可以调整的地方，不必用一次结果衡量自己的价值。"},"career":{"h":"对自己感到懊恼时","t":"犯错或遇到挫折后，先核对事实，不要立刻把它变成对能力的否定。找出一件可以补救的事，以及一个能帮助自己再试一次的条件。如果你已经精疲力尽，休息也可以是稳妥回应的一部分，并不代表失败。"},"wealth":{"h":"综合提示","t":"力量牌常被理解为一种沉稳回应的练习：面对强烈情绪或困难处境时，不让一时的急迫替你决定下一步。它并不是要你压抑愤怒或忍受伤害，而是邀请你留意什么需要照顾、哪里需要设下界限，以及怎样的"},"next":"今天，在你预计要作出的一次回应前，先停两分钟。写下自己能影响的结果、无法控制的部分，以及一个力所能及的平静行动，再决定现在行动，还是稍后重新考虑。"},{"n":9,"name":"隐者","img":"09_Hermit.jpg","intro":"隐者常与有意识的沉淀、学习以及暂时远离喧闹有关。它可以提醒你放慢脚步，听听自己的判断；同时也让你留意，安静独处是在帮助你理清思路，还是让你更难开口求助。","love":{"h":"一次紧张谈话之后","t":"如果谈话后需要一点空间，可以直接说出这个需要，而不是突然失联。约定何时再继续沟通，并利用这段暂停想清楚要表达什么：是需要设定界限、道歉，还是请求一些时间。"},"study":{"h":"工作或学习时","t":"面对研究或较难的任务，可以安排一段安静时间，先明确要解决的问题和结束时间。记下新发现，再向能帮你检查假设或梳理下一步的人简要汇报。"},"career":{"h":"发现自己总想独处时","t":"如果你开始拒绝所有邀约，或把困难完全藏起来，先别急着把这称为独立。选一位信任的人，只分享自己愿意谈的部分，并具体说明你需要陪伴还是某种实际帮助。"},"wealth":{"h":"综合提示","t":"隐者常与有意识的沉淀、学习以及暂时远离喧闹有关。它可以提醒你放慢脚步，听听自己的判断；同时也让你留意，安静独处是在帮助你理清思路，还是让你更难开口求助。"},"next":"留出十分钟安静时间，围绕眼前的一件事写下：你确定知道什么、正在假设什么，以及还有什么需要向别人确认。最后决定是继续梳理，还是联系一个人。"},{"n":10,"name":"命运之轮","img":"10_Wheel_of_Fortune.jpg","intro":"命运之轮常与周期、境况变化，以及计划改变时我们的应对方式有关。它不保证好运降临，也不能解释事情为何发生。作为反思提示，它可以帮助你分辨哪些部分仍在自己影响范围内，以及何时需要耐心或灵活调整。","love":{"h":"关系中反复出现的相处模式","t":"留意熟悉的争执或疏远通常在什么情形下出现。把重点放在看得见的行动，包括自己的回应，而不是猜测对方的想法。尝试调整一条边界，或进行一次更平和的沟通，观察这个模式是否有所变化。"},"study":{"h":"抽到逆位时","t":"如果同一个障碍一再出现，可以看看是否有某种反复的应对方式让自己陷在原地。你不必急着强行改变。先做一项小调整，给它一些时间，再观察情况是否更清楚，然后决定接下来怎么做。"},"career":{"h":"工作计划发生变化时","t":"先分清哪些变化在你的影响范围内，哪些不由你掌控。检查眼下最需要处理的事项，例如期限或沟通，再决定哪些安排可以调整。保留弹性的计划，有助于你回应变化，同时不放弃真正看重的事。"},"wealth":{"h":"综合提示","t":"命运之轮常与周期、境况变化，以及计划改变时我们的应对方式有关。它不保证好运降临，也不能解释事情为何发生。作为反思提示，它可以帮助你分辨哪些部分仍在自己影响范围内，以及何时需要耐心或"},"next":"画一个简单的圆，在圆上标出一种反复出现的情境。旁边写下哪些部分由你影响，以及下次遇到类似情况时，可以尝试的一种小小不同做法。"},{"n":11,"name":"正义","img":"11_Justice.jpg","intro":"正义牌常让人留意自己如何评估一件事，以及采用的标准是否一致。它不是来自外界的裁决，而是一个反思提示：分清事实与推测，看看自己在其中承担什么责任，再选择符合个人价值的回应。","love":{"h":"反复出现的关系分歧","t":"如果同一分歧不断出现，先说清楚具体争议的行为，而不是给某个人贴标签。回顾彼此约定过什么，再想想怎样补救或设立边界才合乎双方的实际需要。讨论时尽量依据看得见的例子。"},"study":{"h":"工作或学习中","t":"试着比较自己评估相似付出的方式，也把自己的表现纳入其中。找出一套能够清楚说明的标准，并留意信息不足是否影响了判断。如果确实有疏失，想一个与问题相称的处理办法。"},"career":{"h":"准备作出选择时","t":"把已知事实、个人推测和仍不确定的部分分开写下。检查自己是否用同一标准衡量每个选项。如果情况还不完整，就判断接下来能合理收集哪些信息。"},"wealth":{"h":"综合提示","t":"正义牌常让人留意自己如何评估一件事，以及采用的标准是否一致。它不是来自外界的裁决，而是一个反思提示：分清事实与推测，看看自己在其中承担什么责任，再选择符合个人价值的回应。"},"next":"画出三栏，分别写下已知事实、个人推测和仍需核实的内容。每栏先填一项，再选一个有助于厘清情况的小行动，不必一次决定所有事情。"},{"n":12,"name":"倒吊人","img":"12_Hanged_Man.jpg","intro":"当熟悉的应对方式不再奏效时，倒吊人可以成为一个反思提示。与其把暂停理解成只能等待，不如借此看看自己可能忽略了什么、为了维持现状正在放弃什么，以及哪些小选择仍由自己决定。","love":{"h":"一场关系对话","t":"如果对话总在原地打转，可以把双方实际说过的话或做过的事，与自己的解读分开写下。然后找出一个可以直接询问的问题，不要预先替答案下结论。这样能让讨论更具体，也更公平。"},"study":{"h":"工作或学习","t":"工作或学习进度放慢时，先别急着投入更多精力。重新检查任务要求、自己对要求的理解，以及收到过的反馈。选一个调整方式试试看，并设定时间回头评估效果。"},"career":{"h":"等待开始变得无益时","t":"留意这段暂停是否带来了更清楚的信息，还是只让你一再推迟一场难谈的对话或一项任务。说清自己在回避什么，采取一个力所能及的小行动，并设定重新评估的日期，别让等待没有期限。"},"wealth":{"h":"综合提示","t":"当熟悉的应对方式不再奏效时，倒吊人可以成为一个反思提示。与其把暂停理解成只能等待，不如借此看看自己可能忽略了什么、为了维持现状正在放弃什么，以及哪些小选择仍由自己决定。"},"next":"把你目前的一项判断写成一句话。在下面分别记下一条支持它的事实、一条可能被忽略的事实，以及一种其他解释。第二天再读一遍，然后决定下一步怎么做。"},{"n":13,"name":"死神","img":"13_Death.jpg","intro":"死神牌通常与结束、过渡或放下有关，为变化腾出空间。它并不预言现实中的死亡，也不自动代表分手；具体含义仍取决于你的问题和整组牌面。","love":{"h":"感情问题","t":"这张牌并不能证明一段关系必须结束。它可以提示你留意正在改变的相处模式、需要表达的事情，以及双方是否都愿意参与这场变化。"},"study":{"h":"抽到逆位时","t":"如果内心仍在留恋，过渡可能显得迟缓。你不必强迫自己做出戏剧性的结束；一个小小的告别动作或更清晰的边界，也可以成为开始。"},"career":{"h":"工作或生活转变","t":"想想某个角色、习惯或期待是否已不再适合自己。做重大决定前，先分清已知事实与担忧，并确认需要哪些现实支持。"},"wealth":{"h":"综合提示","t":"死神牌通常与结束、过渡或放下有关，为变化腾出空间。它并不预言现实中的死亡，也不自动代表分手；具体含义仍取决于你的问题和整组牌面。"},"next":"分别写下准备放下的事，以及仍值得照顾或收尾的事。再从中挑一项自己能够完成的小行动。"},{"n":14,"name":"节制","img":"14_Temperance.jpg","intro":"节制牌常邀请人们在不同需求、习惯或观点之间寻找可行的步调。它不要求你立刻让一切都协调起来，而是帮助你留意：哪些小调整、一些时间或更清晰的界限，能让眼前的处境更容易应对。","love":{"h":"在关系中协调彼此需求","t":"留意双方是否都在为彼此腾出空间，还是主要由一方不断迁就。可以平静地谈谈时间安排、责任分配或界限，看看能否找到更适合双方的相处方式。"},"study":{"h":"安排工作或学习任务","t":"看看一周里的任务是如何分布的。如果每件事都显得很急，挑出一个可以调整的截止时间、承诺或日常安排，再观察改变后是否有足够时间专注完成工作。"},"career":{"h":"抽到逆位时","t":"如果不同要求难以兼顾，把占用注意力的事项写下来，并注明各自实际需要什么。区分真正的责任与可以重新商量的习惯或期待，然后做一项小幅调整。"},"wealth":{"h":"综合提示","t":"节制牌常邀请人们在不同需求、习惯或观点之间寻找可行的步调。它不要求你立刻让一切都协调起来，而是帮助你留意：哪些小调整、一些时间或更清晰的界限，能让眼前的处境更容易应对。"},"next":"画两栏，分别写上“需要”和“要求”，列出各自占用了你哪些时间。选一项小小的界限或日程调整，在本周试行，再留意哪些事情变轻松了，哪些仍需处理。"},{"n":15,"name":"恶魔","img":"15_Devil.jpg","intro":"恶魔牌常与执着、诱惑，以及我们不太愿意面对的内在部分相关。它并不是在评判你好坏，也不表示你无能为力；它可以邀请你看看什么持续吸引着你、为此付出了什么，以及仍有哪些选择。","love":{"h":"感情问题","t":"可以借这张牌观察自己的边界和反复出现的互动，而不是据此猜测对方在想什么。留意自己何时勉强答应、试图回避什么，以及有哪些清楚的请求或界限可以表达出来。"},"study":{"h":"反复出现的日常习惯","t":"挑一个容易不假思索就发生的行为，例如拖延任务或拿起手机。记录它出现前发生了什么、它当下带来了什么，再想一个下次可以尝试的小调整。"},"career":{"h":"抽到逆位时","t":"看看有没有什么处境是你习惯独自藏着的。写下能观察到的后果、你对它讲述的故事，以及哪位可信任的人或什么环境能让坦诚迈出下一步时更安心。"},"wealth":{"h":"综合提示","t":"恶魔牌常与执着、诱惑，以及我们不太愿意面对的内在部分相关。它并不是在评判你好坏，也不表示你无能为力；它可以邀请你看看什么持续吸引着你、为此付出了什么，以及仍有哪些选择。"},"next":"用一天时间记下自己被熟悉模式牵着走的时刻：当时的诱因、自己的反应，以及下次可以选择的另一种做法。把记录当作了解情况的线索，而不是对自己的定论。"},{"n":16,"name":"高塔","img":"16_Tower.jpg","intro":"高塔牌常与突变、视角改变或需要重新审视的结构有关。它并不能证明灾难即将发生。可以借它思考已经确认的事实、需要关注的地方，以及哪些回应仍在自己掌控之中。","love":{"h":"感情问题","t":"与其把牌面解读成分手预言，不如思考有哪些事情难以表达或维持。关注可观察到的行为、彼此边界，以及坦诚沟通是否安全且有帮助。"},"study":{"h":"抽到逆位时","t":"你也许已经察觉压力，却仍想让一切保持原样。适度调整可能比等待绝对确定，或强行推倒重来更有帮助。"},"career":{"h":"工作或突然的变化","t":"把已经确认的变化与传闻、最坏设想分开。收集必要信息，先照顾眼前责任，并在根据新情况重做计划前给自己一些时间。"},"wealth":{"h":"综合提示","t":"高塔牌常与突变、视角改变或需要重新审视的结构有关。它并不能证明灾难即将发生。可以借它思考已经确认的事实、需要关注的地方，以及哪些回应仍在自己掌控之中。"},"next":"分别写下已知事实、自己的假设，以及一项值得确认的现实问题。从能让情况更清楚或更稳定的小步骤开始。"},{"n":17,"name":"星星","img":"17_Star.jpg","intro":"星星牌常与希望、更新，以及经历压力后重新找回意义感有关。它并不保证处境会自行好转，而是邀请你留意什么能让自己恢复安定、为休息留出空间，并通过微小而持续的行动滋养灵感。","love":{"h":"感情问题","t":"让希望建立在能够观察到的事情上。留意关心是否体现在持续的行动中，也可以表达一个善意举动，但不必期待它立刻消除所有不确定。与其猜测，不如平静地聊聊彼此怎样更容易感到支持。"},"study":{"h":"工作或学习压力之后","t":"给自己留出恢复的空间，灵感或许更容易回来。找出一项重要任务和一项可以暂缓的事，再安排一段短暂而规律的休息。留意放慢一点之后，自己是否更能想起当初为什么选择这份工作或这门学习。"},"career":{"h":"抽到逆位时","t":"沮丧可能让人觉得可选的路越来越少。与其强迫自己乐观，不如写下一件仍在自己掌控中的事，以及一个可以求助的对象。也可以检查一下，休息或容易坚持的日常安排是否被忽略了。"},"wealth":{"h":"综合提示","t":"星星牌常与希望、更新，以及经历压力后重新找回意义感有关。它并不保证处境会自行好转，而是邀请你留意什么能让自己恢复安定、为休息留出空间，并通过微小而持续的行动滋养灵感。"},"next":"接下来一周，选一个对自己温柔的小举动，并把它安排在日常习惯之后，例如泡茶或合上电脑。每天结束时，简单记下这个举动有没有让自己感觉更安定。"},{"n":18,"name":"月亮","img":"18_Moon.jpg","intro":"月亮牌常与直觉、模糊，以及尚未完全明朗的事情有关。它可以提醒你留意情绪上的感受，但不要把感受直接当成事实。放慢脚步，分清观察与猜测，再依据更清楚的信息决定下一步。","love":{"h":"感情问题","t":"试着分清对方实际说过或做过什么，以及你担心沉默代表什么。如果有些事不明朗，可以记下具体行为，再考虑平静、直接地沟通，而不是用想象填补空白。"},"study":{"h":"工作或学习","t":"不确定时，模糊的担忧容易被误当成结论。列出已知事实、缺少的信息，以及谁能帮你确认；再把任务拆成一个小步骤。不要只凭深夜的担心就做重大选择。"},"career":{"h":"抽到逆位时","t":"留意反复担忧是否让视野变窄，或让自己一直处于戒备中。想一条有帮助的边界，例如暂停消耗性的对话，或减少寻求保证的次数。等状态平稳些，再重新审视这件事。"},"wealth":{"h":"综合提示","t":"月亮牌常与直觉、模糊，以及尚未完全明朗的事情有关。它可以提醒你留意情绪上的感受，但不要把感受直接当成事实。放慢脚步，分清观察与猜测，再依据更清楚的信息决定下一步。"},"next":"分两栏写下“我观察到的”和“我正在猜测的”。把每个担忧分别归类，再挑一项猜测，通过可靠来源或清楚的沟通来核实。信息还不够时，先不急着下结论。"},{"n":19,"name":"太阳","img":"19_Sun.jpg","intro":"太阳牌常与温暖、活力和愉悦感相关。它可以邀请你留意哪些事情正在顺利发生，让当下的好时刻真正沉淀下来，而不是每有一点成果就立刻设定下一个目标。它关注的是觉察与平衡，并不保证成功。","love":{"h":"感情关系中","t":"这张牌可以邀请你留意彼此相处时感到自在的时刻。说出一件你欣赏的事，为共同的愉快留些空间，但不必把一段美好时光当作关系未来走向的证明。"},"study":{"h":"工作或学习中","t":"留意可以确认的进展，例如完成的任务、练习过的技能或有帮助的反馈。在添加下一个目标前，先认可这份成果，也看看目前的节奏是否为休息留有余地。"},"career":{"h":"受到赞赏也感到压力时","t":"受到关注或面对高期待时，享受已有成果可能变得不容易。留意哪些要求来自他人，哪些是自己加给自己的。决定下一步之前，你可以先用更安静的方式肯定这份进展。"},"wealth":{"h":"综合提示","t":"太阳牌常与温暖、活力和愉悦感相关。它可以邀请你留意哪些事情正在顺利发生，让当下的好时刻真正沉淀下来，而不是每有一点成果就立刻设定下一个目标。它关注的是觉察与平衡，并不保证成功。"},"next":"写下一项近期成果，以及促成它的具体努力。今天选一种小方式来享受或肯定这份成果；至于下一个目标，可以等到明天再写。"},{"n":20,"name":"审判","img":"20_Judgement.jpg","intro":"审判牌常被视为一次回顾：看见一段经历带给自己的启发，并决定此刻什么值得关注。它不能确认唯一的“正确道路”，也不要求你戏剧性地重新开始。你可以借它留意自己的进步，辨认哪些已不再适合，并按自己的节奏迈出下一步。","love":{"h":"感情问题","t":"用这张牌回顾自己能观察到的相处模式，而不是判断对方的感受。指出一段重要对话或反复出现的行为，再想想自己希望改变、延续或说清什么。关系能否焕新，仍取决于彼此的选择与行动。"},"study":{"h":"工作或学习","t":"回顾一项已完成的任务、收到的反馈或遇到的挑战，记下其中的收获。把成长的实际证据与证明自己的压力区分开来，再选一项接下来想培养的技能或承担的职责，不必把牌意当作重大变动的命令。"},"career":{"h":"仍在纠结过去的选择","t":"分清哪些事情还可以补救，哪些已经不在你的掌控之中。写下一条经验，但不要因此给整个人格下评判；之后选一个能帮助自己继续前进的小行动。"},"wealth":{"h":"综合提示","t":"审判牌常被视为一次回顾：看见一段经历带给自己的启发，并决定此刻什么值得关注。它不能确认唯一的“正确道路”，也不要求你戏剧性地重新开始。你可以借它留意自己的进步，辨认哪些已不再适合，"},"next":"设定十分钟计时，简短写下三点：发生了什么、学到了什么、下次想如何处理。圈出一件本周可以做的事，并把它定得足够小，不必等到完全有把握才开始。"},{"n":21,"name":"世界","img":"21_World.jpg","intro":"世界牌常被视为一个回顾的时刻，让你看见持续努力后逐渐汇聚起来的成果。它不要求一切都完美收尾，而是可以邀请你留意学到了什么、还有哪些部分需要照料，并思考如何带着这段经历继续前行。","love":{"h":"回顾一段关系","t":"如果你正在回看共同经历的一段时光，可以说说彼此付出了什么，还有哪些话或事情尚未处理。谈谈感谢、后续安排或边界，能让收尾感更清晰，但不必预设关系一定要改变。"},"study":{"h":"抽到逆位时","t":"别只用尚未完成的部分来评价整段历程，可以比较现在与起点的不同。找出一项仍然重要的待办，也留意一个可能被忽略的进展。再决定要完成、委托他人，还是有意识地暂时搁置。"},"career":{"h":"完成一个项目","t":"列出最初的目标、已经完成的部分，以及还没处理的事项。把必要的收尾和可选的润色分开，再定下明确的停笔点或复查日期。这样既能看见自己的投入，也不必要求每个细节都完美无缺。"},"wealth":{"h":"综合提示","t":"世界牌常被视为一个回顾的时刻，让你看见持续努力后逐渐汇聚起来的成果。它不要求一切都完美收尾，而是可以邀请你留意学到了什么、还有哪些部分需要照料，并思考如何带着这段经历继续前行。"},"next":"画一个简单的圆，分成三块：已经完成的事、学到的经验、还需要推进的事项。本周挑一件小事收尾，其余的标记为稍后处理，或决定放下。"},{"n":22,"name":"权杖一","img":"Wands01.jpg","intro":"权杖一常被视为创意能量初现：一个值得探索的念头、冲动或可能性。火花还不是完整计划，后续发展也取决于你选择如何回应。这张牌可以帮助你留意，哪些兴趣正等待一个实际的出口。","love":{"h":"动力减弱时","t":"如果你仍在意这个念头，却迟迟难以开始，就把下一步设得明确而短小。打开文档、写下粗略的第一句，或准备好所需物品。之后再决定继续、调整还是暂时停下。"},"study":{"h":"工作或学习","t":"如果一种新方法让你感兴趣，先设定一个规模最小、仍有参考价值的试行步骤。想想要了解什么、需要告知谁，以及何时回顾结果，让热情也顾及现实责任。"},"career":{"h":"创意项目","t":"从想法中挑出一个不必承诺整个项目也能试做的部分。可以先画个草稿、准备几样材料，或留出二十分钟动手。留意实际操作后思路是否更清楚，或是否发现了值得处理的障碍。"},"wealth":{"h":"综合提示","t":"权杖一常被视为创意能量初现：一个值得探索的念头、冲动或可能性。火花还不是完整计划，后续发展也取决于你选择如何回应。这张牌可以帮助你留意，哪些兴趣正等待一个实际的出口。"},"next":"写下一个你想探索的点子，再列出一项今天十五分钟内能完成的任务。先把这项任务做完，再考虑如何扩展计划。"},{"n":23,"name":"权杖二","img":"Wands02.jpg","intro":"权杖二常被视为一个向熟悉领域之外张望、同时留意已有基础的时刻。它可以帮助你思考方向与规模，但不会替你决定是否前进。借由这张牌，你可以梳理自己想探索什么，以及需要哪些准备，才能让尝试更可行。","love":{"h":"规划一段关系","t":"如果你正在考虑改变关系中的相处方式，先说清楚希望有什么不同，以及哪些部分想要保留。讨论时间、距离或共同责任等现实细节，再把对未来的设想变成可执行的计划。"},"study":{"h":"工作或学习计划","t":"面对新职位、课程或项目，先列出已有的技能与资源，再找出最主要的缺口。可以向熟悉相关领域的人了解第一阶段需要做什么，帮助自己设定符合实际能力的范围。"},"career":{"h":"抽到逆位时","t":"留意自己是在推迟一个做得到的小步骤，还是一次承担了太多事情。写下一个最小的阶段目标，再为时间或资源设定一项限制。先调整计划，再决定是否增加新的承诺。"},"wealth":{"h":"综合提示","t":"权杖二常被视为一个向熟悉领域之外张望、同时留意已有基础的时刻。它可以帮助你思考方向与规模，但不会替你决定是否前进。借由这张牌，你可以梳理自己想探索什么，以及需要哪些准备，才能让尝试"},"next":"画两栏，分别写下已有条件和下一步所需的准备。从中挑一件小事来检验计划，例如核对时间安排或补充一项资料，再考虑是否作出更大的承诺。"},{"n":24,"name":"权杖三","img":"Wands03.jpg","intro":"权杖三常与跳出眼前事务、思考投入将通向何处有关。它可以邀请你拓宽视角，但不保证某种结果。留意已经开始的事情、尚不确定的部分，以及根据目前掌握的信息，哪一步最适合现在采取。","love":{"h":"关系或合作","t":"想想你和对方对接下来的方向是否有实际共识。对照彼此约定要做的事与实际进展，再找出一项需要通过沟通说清楚的期待。"},"study":{"h":"计划似乎偏离方向时","t":"根据眼下的限制重新检查计划，例如时间、可用支持和新出现的信息。不要把进展缓慢直接当作定论；找出一处可以调整的部分，以及一处仍值得保留的安排。"},"career":{"h":"工作或正在发展的项目","t":"盘点哪些想法已经落实为行动。记下哪些任务正在推进、哪些环节需要等待他人，以及规划下一阶段还需要什么信息。拉远视角有助于理清优先事项，但不必因此认定事情一定会成功。"},"wealth":{"h":"综合提示","t":"权杖三常与跳出眼前事务、思考投入将通向何处有关。它可以邀请你拓宽视角，但不保证某种结果。留意已经开始的事情、尚不确定的部分，以及根据目前掌握的信息，哪一步最适合现在采取。"},"next":"画一条简单的时间线，从现在延伸到三个月后。标出一项进展、一个尚待解答的问题，以及本周可以采取的一件小行动，用来了解更多情况。"},{"n":25,"name":"权杖四","img":"Wands04.jpg","intro":"权杖四常与共同的喜悦、归属感，以及让人安定下来的支持有关。它可以邀请你留意什么让一个地方或群体显得温暖，同时也提醒你：庆祝的时刻并不代表所有顾虑都已消失。","love":{"h":"庆祝共同的里程碑","t":"团队、家庭或社群达成一个阶段性目标后，不妨说说每个人具体做了什么，而不是把成果看成理所当然。可以用简单的方式庆祝，也可以聊聊哪些做法帮助大家合作，让有效的部分延续到下一阶段。"},"study":{"h":"与身边的人相处时感到自在","t":"归属感既可能来自一个地方，也可能来自日常相处。留意自己何时能在身边的人面前放松，以及哪些实际安排带来了舒适感。如果聚会气氛有些紧绷，可以找个安静时刻关心彼此，而不是默认大家都没事。"},"career":{"h":"抽到逆位时","t":"如果表面的庆祝和私下感受不太一致，可以先找出一处具体的不自在，而不要把牌当成存在隐情的证据。想想有哪些话还没说、谁是适合沟通的人，再找个平静的时机倾听或表达自己的需要。"},"wealth":{"h":"综合提示","t":"权杖四常与共同的喜悦、归属感，以及让人安定下来的支持有关。它可以邀请你留意什么让一个地方或群体显得温暖，同时也提醒你：庆祝的时刻并不代表所有顾虑都已消失。"},"next":"写下最近一次感到被接纳的时刻，再记下当时有哪些人、习惯或边界带来了支持。本周选一个小行动来巩固这种支持，例如表达感谢，或和他人约定一个共同的日常安排。"},{"n":26,"name":"权杖五","img":"Wands05.jpg","intro":"权杖五可以让你留意不同意见、彼此竞争的做法，以及寻找共同点所需的努力。它不会替你判定谁对谁错，也不代表每场争论都有价值。可以借这张牌看看争论的焦点是什么、你重视什么结果，以及当下的沟通方式是否有助于实现它。","love":{"h":"感情中的分歧","t":"如果同一个争执反复出现，先说清双方说法具体在哪一点不同，而不是争论彼此的性格或动机。回应前，可以先复述对方的看法；如果这很难做到，就暂停一下，并约好何时再谈。"},"study":{"h":"抽到逆位时","t":"如果争论一直兜圈子，留意有没有人获得新信息或改变看法。可以设定讨论时限，重新说明眼下需要解决的决定；如果对话变成针对个人，就先离开，等有了实际的下一步再继续。"},"career":{"h":"团队或课堂项目","t":"把不同方案列出来，对照共同目标逐项比较，再明确由谁负责测试或决定各个部分。这样可以把热烈的争论转成具体任务，并确定接下来要做什么以及何时回顾。"},"wealth":{"h":"综合提示","t":"权杖五可以让你留意不同意见、彼此竞争的做法，以及寻找共同点所需的努力。它不会替你判定谁对谁错，也不代表每场争论都有价值。可以借这张牌看看争论的焦点是什么、你重视什么结果，以及当下的"},"next":"用一句话写下分歧，再记下你希望达成的结果，以及一个能帮助你了解对方立场的问题。找个平静、具体的时机提出它；如果暂时不合适，也可以先留着。"},{"n":27,"name":"权杖六","img":"Wands06.jpg","intro":"权杖六让人留意自己被看见时的感受。你可以借此观察自己为哪些事情付出过、哪些人的反馈对你有参考价值，以及能否在听取他人意见的同时，也用自己的标准看待进步。","love":{"h":"分享创作成果","t":"发布或展示作品前，先想好哪些回应对你有帮助，哪些内容希望保留在私人范围。之后，把可操作的建议和笼统的认可分开，再挑一条带进下一版创作中。"},"study":{"h":"完成工作或学习阶段目标后","t":"花点时间记录自己具体做了什么，不只看最后的结果。有人给你反馈时，记下其中具体且有用的部分。这样能更清楚地看见自己的进展，而不是一味否定赞赏，或完全依赖赞赏来判断自己。"},"career":{"h":"受到关注时感到不自在","t":"留意注意力转向自己时，身体和念头有什么变化。你可能会转移话题、拿自己和别人比较，或觉得必须继续表现。试着简单地说声谢谢，再想想自己如何评价这份努力。"},"wealth":{"h":"综合提示","t":"权杖六让人留意自己被看见时的感受。你可以借此观察自己为哪些事情付出过、哪些人的反馈对你有参考价值，以及能否在听取他人意见的同时，也用自己的标准看待进步。"},"next":"写下一件近期让你认可自己的付出、一条收到的反馈，以及一项你为自己设定的标准。对照这三者，再选一个不依赖更多掌声的下一步。"},{"n":28,"name":"权杖七","img":"Wands07.jpg","intro":"权杖七可以让你留意那些感到受挑战、需要说明立场的时刻。它邀请你想想什么值得守护，以及自己的回应是否仍为有效沟通留有空间。坚持一项价值观，并不意味着要把每个不同意见都视为威胁。","love":{"h":"感情中的意见分歧","t":"与其争论每个细节，不如先说清楚涉及哪条界限或哪项价值。听听对方实际提出了什么，再决定哪些内容可以商量、哪些对你而言不能让步。适时暂停，也能避免表达立场演变成冲突升级。"},"study":{"h":"工作或学习中表达立场","t":"如果你需要提出想法或守住合理的限度，可以准备两三个清晰要点和相关例子。想想这场讨论需要达成什么结果，也欢迎能改进方案的问题。这样能让表达聚焦，而不必对每项批评都急着辩解。"},"career":{"h":"每场争论都让你感到紧迫时","t":"留意这件事是否触及你的价值观，还是主要引发了非要争对错的念头。你可以只回应一个重点、让小分歧先过去，或约个更平和的时间再谈。节省精力可以是主动选择，并不等于认输。"},"wealth":{"h":"综合提示","t":"权杖七可以让你留意那些感到受挑战、需要说明立场的时刻。它邀请你想想什么值得守护，以及自己的回应是否仍为有效沟通留有空间。坚持一项价值观，并不意味着要把每个不同意见都视为威胁。"},"next":"写下一件让你感到受挑战的事，再列出涉及的价值观或界限、你希望达成的结果，以及一句能尊重地表达立场的话。提前想好哪些部分愿意讨论。"},{"n":29,"name":"权杖八","img":"Wands08.jpg","intro":"权杖八常与节奏、协调以及接连到来的信息有关。行动很快，并不等于你必须匆忙决定。这张牌可以邀请你留意哪些事情已经开始推进，确认自己是否理解现状，再选择把注意力放在哪里。","love":{"h":"一段关系中的沟通","t":"消息或计划来得很快时，先别急着用猜测填补空白。确认对方实际说了什么，讲清对你重要的部分，再提出一个明确的追问。即使交流节奏很快，你仍可以留出时间认真回应。"},"study":{"h":"工作或学习","t":"几项请求可能同时占据你的注意力。把它们写下来，标出真正的期限，并看看哪些任务彼此关联。这样更容易有效回应，也能避免把紧迫误当成重要，或漏看有用的信息。"},"career":{"h":"计划或消息变得混乱时","t":"如果细节零散地传来，不必试图一次解决所有事情。把相关记录放在一起，向有关的人确认下一步，并先标记尚不清楚的部分，留待追问，而不是自行猜测。"},"wealth":{"h":"综合提示","t":"权杖八常与节奏、协调以及接连到来的信息有关。行动很快，并不等于你必须匆忙决定。这张牌可以邀请你留意哪些事情已经开始推进，确认自己是否理解现状，再选择把注意力放在哪里。"},"next":"花两分钟写下正在推进的事、需要确认的事，以及可以稍后处理的事。圈出一项作为下一步，然后暂时放下清单，专心完成它。"},{"n":30,"name":"权杖九","img":"Wands09.jpg","intro":"权杖九常与持续努力后的韧性和警觉有关。它并不是要你靠不停坚持来证明自己。作为反思提示，它可以帮助你看看哪些事仍然重要、当前精力允许做到什么，以及怎样设定适度的边界，让努力能够持续下去。","love":{"h":"为关系设定边界","t":"如果你在一段关系中有所防备，先指出具体是哪种行为让你谨慎，而不要猜测对方的意图。用简单的话说清一条边界，再留意自己的行动和交流是否与之相符。你可以保持开放，同时给自己时间重新建立信任。"},"study":{"h":"一项耗时很久的任务","t":"如果一项任务拖了很久，不妨把剩余部分列出来，而不是把全部工作看成一个沉重的整体。设定现实的结束时间，留出一段短暂休息，再看看今天真正需要你处理的是哪一部分。这样有助于分清持续投入与超出限度的硬撑。"},"career":{"h":"抽到逆位时","t":"如果你一直在提防下一个麻烦，先分清眼前可观察到的问题和对未来的预想。判断需要做多少准备才算合适，并给自己一段明确的休息时间，再重新评估。精力耗尽时，你不必急着解决所有担忧。"},"wealth":{"h":"综合提示","t":"权杖九常与持续努力后的韧性和警觉有关。它并不是要你靠不停坚持来证明自己。作为反思提示，它可以帮助你看看哪些事仍然重要、当前精力允许做到什么，以及怎样设定适度的边界，让努力能够持续下"},"next":"设定五分钟计时，写下一项优先事项、一件可以延后的任务，以及今天能安排的一种休息。选出最小的下一步，并在设定的时间到后停下来。"},{"n":31,"name":"权杖十","img":"Wands10.jpg","intro":"权杖十常让人留意自己承担了多少，以及这些努力究竟为了什么。它可以邀请你诚实地盘点责任、界限和优先顺序。这张牌并不是要你独自处理一切，而是提醒你思考哪些事情值得投入精力，以及是否需要调整做法。","love":{"h":"家庭与照护责任","t":"照护任务不断累积时，可能很难看清它们各自占用了多少精力。写下反复出现的事务，再找出一项可以请人接手或简化的内容。围绕时间和能力进行一次实际沟通，或许能让安排更可持续。"},"study":{"h":"工作或学习中","t":"列出手头的任务，标出本周确实需要你处理的事项。如果某项责任可以分担，就提出具体请求，并说明各自负责什么。这样有助于分清真正的优先事项，以及习惯性地把所有事情都揽下来的部分。"},"career":{"h":"计划进展不顺时","t":"如果事情进展变慢，可以看看哪项任务或期待最耗费精力。想想它是否仍然重要、能否延期，以及怎样的支持能让它变得可行。调整计划并不代表失败，你可以根据现实情况重新安排。"},"wealth":{"h":"综合提示","t":"权杖十常让人留意自己承担了多少，以及这些努力究竟为了什么。它可以邀请你诚实地盘点责任、界限和优先顺序。这张牌并不是要你独自处理一切，而是提醒你思考哪些事情值得投入精力，以及是否需要"},"next":"快速写下所有占据你注意力的事情。本周圈出一项准备分担、简化或暂缓的任务，再选定一位可以沟通的人，或一个能帮助你落实的实际步骤。"},{"n":32,"name":"权杖侍从","img":"Wands11.jpg","intro":"权杖侍从可以让你留意新兴趣，或尚在成形中的点子。与其把热情当作事情一定能成功的证明，不如把它当成进一步了解的理由。一次小尝试，能帮助你看清什么值得投入时间，什么还需要仔细核实。","love":{"h":"一段新的联结","t":"如果你对某个人感到好奇，可以留意通过交谈和相处实际了解到的内容。试着提出一个开放而具体的问题，或约一次轻松的活动。让关系按彼此都感到自在的节奏发展，并尊重双方的边界。"},"study":{"h":"工作或学习中的新点子","t":"有趣的点子不必等到计划完整才开始了解。先写下自己想弄清楚什么，再选一项简短的资料搜集任务，或进行一次低成本的试验。留意结果是让你更感兴趣、发现限制，还是提示你调整方向。"},"career":{"h":"抽到逆位时","t":"如果你很想立刻下结论，可以先把核实过的内容和自己的假设分开。找到说法的原始出处，确认一项重要细节，并且只安排一个下一步任务。这样有助于避免精力分散。"},"wealth":{"h":"综合提示","t":"权杖侍从可以让你留意新兴趣，或尚在成形中的点子。与其把热情当作事情一定能成功的证明，不如把它当成进一步了解的理由。一次小尝试，能帮助你看清什么值得投入时间，什么还需要仔细核实。"},"next":"用一句话写下一个新点子，设定二十分钟，核实一项事实、画出初步构想，或列出最小规模的尝试。完成后记下自己学到了什么，再决定是否继续。"},{"n":33,"name":"权杖骑士","img":"Wands12.jpg","intro":"权杖骑士常与主动、热情以及推动事情发生的意愿相关。作为反思提示，它可以帮助你留意精力投向何处，以及接下来的行动是否服务于真正重要的事，而不只是让自己一直忙碌。","love":{"h":"感情关系中","t":"留意热情是否也伴随着关注和持续的行动。如果你想拉近距离或谈谈顾虑，可以明确说出一项具体请求，也给对方回应的空间，而不是只凭猜测行事。"},"study":{"h":"工作或学习中","t":"把精力用在一个有明确下一步的任务上。接下新的事情前，先检查已有安排，再决定哪些可以暂缓、委托或先完成，避免精力分散。"},"career":{"h":"项目进展过快时","t":"如果进展变得慌乱或忽快忽慢，停下来看看当前节奏是否符合你想要的结果。为本周选定一个优先事项，并设定投入时间或精力的上限。"},"wealth":{"h":"综合提示","t":"权杖骑士常与主动、热情以及推动事情发生的意愿相关。作为反思提示，它可以帮助你留意精力投向何处，以及接下来的行动是否服务于真正重要的事，而不只是让自己一直忙碌。"},"next":"写下目前最耗费你精力的目标，再列出一项能推动它的行动，以及一个提醒自己暂停并重新评估的信号。把行动安排在现实可行的时间段里。"},{"n":34,"name":"权杖王后","img":"Wands13.jpg","intro":"权杖王后常与温暖、创造力和自我认同相关。这张牌可以邀请你留意什么让自己投入其中，以及你如何表达自己；至于要分享多少精力，仍由你决定。","love":{"h":"感情关系中","t":"留意自己能否自然地展现个性，而不是一味迎合认可。清楚说出一项偏好或界限，也给对方回应的空间。温暖的相处可以容纳坦诚、不同意见，也可以有各自独处的时间。"},"study":{"h":"抽到逆位时","t":"看看自己的精力花在哪里，哪些事情让你感到消耗。接下新任务前可以先停一停，也可以想想最近的选择是否符合自己的优先事项。短暂休息或许能帮助你更从容地回应。"},"career":{"h":"创作项目中","t":"挑一个暂时搁置的想法，把它变成小小的实际成果，例如草稿、图稿或提案。分享之前，先想清楚自己需要什么样的反馈，别让别人的反应取代你原本的目标。"},"wealth":{"h":"综合提示","t":"权杖王后常与温暖、创造力和自我认同相关。这张牌可以邀请你留意什么让自己投入其中，以及你如何表达自己；至于要分享多少精力，仍由你决定。"},"next":"设定十分钟，做一样不必考虑观众评价的东西：画几笔、写几行，或列出一些点子。完成后记下过程中哪些部分让你感到愉快，以及还想继续探索什么。"},{"n":35,"name":"权杖国王","img":"Wands14.jpg","intro":"权杖国王常与愿景、信念和领导力相关。作为反思提示，它能帮助你留意自己如何运用影响力，以及所设定的方向是否给他人的想法留有空间。这张牌并不是对你性格的定论；如何带领他人，仍由你自己选择。","love":{"h":"进行一场关系对话","t":"留意自己是否表达了重视的事情，也给对方机会讲述他们的看法。提出解决办法前，先复述你听到的内容，并确认接下来的做法是双方商量的结果，而不是由一方单独决定。"},"study":{"h":"承担重要责任时","t":"如果有人依赖你的判断，看看紧迫感是否让你忽略了其他角度。列出已知事实、自己的假设，以及会受到影响的人。稍作停顿或听取另一种意见，或许能让下一步更周全。"},"career":{"h":"带领团队或项目","t":"清晰的方向有助于团队开始行动。说明目标，也邀请他人提出具体意见，例如你可能忽略的风险或不同做法。之后说清楚，他们的意见会如何影响计划。"},"wealth":{"h":"综合提示","t":"权杖国王常与愿景、信念和领导力相关。作为反思提示，它能帮助你留意自己如何运用影响力，以及所设定的方向是否给他人的想法留有空间。这张牌并不是对你性格的定论；如何带领他人，仍由你自己选"},"next":"写下你想设定的方向，以及一位值得纳入讨论的人。请对方提出一个实际顾虑或建议；如果确有帮助，就据此调整计划中的一个小部分。"},{"n":36,"name":"圣杯一","img":"Cups01.jpg","intro":"圣杯一可以邀请你留意，哪些感受、关怀或创造力正在等待关注。它并不保证某段关系或某种结果，而是提醒你为重视的事留出空间，并思考想以怎样的方式表达。","love":{"h":"感情问题","t":"用这张牌观察自己的感受，而不是据此猜测对方的想法。什么样的交流让你感到舒服、有滋养？留意言行是否符合自己的界限，再选择一种坦诚、没有压力且能持续的表达方式。"},"study":{"h":"抽到逆位时","t":"留意自己是否给予了超出舒适范围的关心，或习惯性地把一切藏起来。你不必分享超过自己意愿的内容。想想什么界限或小小的支持，能让这份联结更平衡。"},"career":{"h":"创作或工作","t":"某种感受或画面即使还不完整，也可以成为创作素材。先记下吸引你注意的东西，再为它安排一个小小的容器：画一张草图、写几条笔记，或专心投入二十分钟。"},"wealth":{"h":"综合提示","t":"圣杯一可以邀请你留意，哪些感受、关怀或创造力正在等待关注。它并不保证某段关系或某种结果，而是提醒你为重视的事留出空间，并思考想以怎样的方式表达。"},"next":"设定五分钟计时，写下一种自己一直带着的感受，再补上一件今天能用尊重自己的方式回应它的小事，例如留出休息、创作或坦诚表达的时间。"},{"n":37,"name":"圣杯二","img":"Cups02.jpg","intro":"圣杯二常让人留意一段联结如何通过倾听、清楚表达，以及为彼此的需要留出空间而建立。它可以对应恋爱、友谊或合作。它不能证明关系是否平等，但可以提醒你对照言语与行动，看看双方如何参与其中。","love":{"h":"感情关系","t":"留意双方是否都会主动联系、顾及彼此的偏好，并兑现说好的事情。如果感觉付出不太对等，可以举出一个具体例子，邀请对方谈谈各自的需要，而不是把牌当作判断对方感受的证据。"},"study":{"h":"工作或学习合作","t":"在工作或学习搭档中，看看职责、成果认可和沟通是否分配清楚。约定各自负责什么，以及遇到问题时如何提出。比起良好的第一印象，持续一致的行动更能帮助你判断是否彼此尊重。"},"career":{"h":"抽到逆位时","t":"逆位时，可以留意期望是否错位，或付出是否不均。写下自己原本期待什么、实际约定了什么，以及自己的界限在哪里。一次平静而具体的谈话，有助于弄清双方是否愿意调整。"},"wealth":{"h":"综合提示","t":"圣杯二常让人留意一段联结如何通过倾听、清楚表达，以及为彼此的需要留出空间而建立。它可以对应恋爱、友谊或合作。它不能证明关系是否平等，但可以提醒你对照言语与行动，看看双方如何参与其中"},"next":"画两栏，分别写下你在一段关系中的付出和收到的回应，并尽量用近期实例而非猜测。圈出一项仍不清楚的地方，再准备一句直接而尊重的话，找机会谈谈。"},{"n":38,"name":"圣杯三","img":"Cups03.jpg","intro":"圣杯三常与友谊、归属感以及值得一起纪念的时刻相关。它可以引导你留意支持如何在群体中流动、谁在为他人留出空间，以及庆祝是否让人感到愉快，而非只是责任。这张牌适合用来反思，并不是对未来的预告。","love":{"h":"筹备一次聚会","t":"确定日期前，想想你希望邀请的人怎样才能感到自在、受到欢迎。可以考虑时间、费用、场地是否方便，以及人数是否合适。清楚说明安排的邀请，能让每个人判断自己是否方便参与，以及如何参与。"},"study":{"h":"需要关照的友谊","t":"想想这段友谊中的关心是否有所往来：通常是谁主动联系、倾听或安排见面？你可以提议一次轻松的碰面，具体说说自己珍惜对方的哪一点，同时也给对方的需求留出空间。"},"career":{"h":"抽到逆位时","t":"如果社交安排让你感到紧张或疲惫，可以先停一停，不急着答应新的邀约。留意谁一直没怎么说话或没有被考虑到，也看看群体惯例是否已不再适合所有人。直接问候一下，或改成规模更小的聚会，可能更容易安排。"},"wealth":{"h":"综合提示","t":"圣杯三常与友谊、归属感以及值得一起纪念的时刻相关。它可以引导你留意支持如何在群体中流动、谁在为他人留出空间，以及庆祝是否让人感到愉快，而非只是责任。这张牌适合用来反思，并不是对未来"},"next":"写下你想邀请来小聚或联系的几个人，选一种方便的方式主动问候，并询问什么时间或形式更适合他们。"},{"n":39,"name":"圣杯四","img":"Cups04.jpg","intro":"圣杯四常被解读为一段向内沉思的时刻，此时注意力可能不在眼前的选择上。它可以邀请你分辨：兴趣减退是否反映了真实意愿，还是你需要休息、理清思路，或换一种方式参与其中。","love":{"h":"关系中的一次对话","t":"如果一段对话或一个邀约让你提不起兴趣，先找出自己觉得缺少了什么：是精力、信任，还是某个需要谈清楚的话题？表达你实际观察到的情况，不要猜测对方的想法，并说出一项能让交流更容易的改变。"},"study":{"h":"工作或学习","t":"当一项任务让你感到乏味时，记下哪些部分消耗你，哪些仍有一点吸引力。想想调整安排、增加支持或缩小范围是否有帮助。这能让你看清自己需要暂停、换种做法，还是坦诚沟通彼此的期待。"},"career":{"h":"重新参与曾经搁置的事","t":"如果你在考虑重新投入某段关系、某项活动或一个项目，具体想想自己有哪些变化。说清需要处理的不满，再选一种压力较小的方式试探兴趣，之后再决定是否作出更大的承诺。"},"wealth":{"h":"综合提示","t":"圣杯四常被解读为一段向内沉思的时刻，此时注意力可能不在眼前的选择上。它可以邀请你分辨：兴趣减退是否反映了真实意愿，还是你需要休息、理清思路，或换一种方式参与其中。"},"next":"安静五分钟，列出最近消耗你精力的事，以及别人向你提出过的事情。圈出一项值得再了解的内容，然后决定是提问、设定界限，还是先休息再回应。"},{"n":40,"name":"圣杯五","img":"Cups05.jpg","intro":"圣杯五常与哀伤，以及为仍然拥有的事物留出空间有关。它并不是要你否认痛苦，也不要求你还没准备好就向前走。它可以提醒你承认失去，同时温和地留意身边仍可依靠的人、资源或日常习惯。","love":{"h":"关系发生变化之后","t":"如果你正在为关系的变化而难过，可以说出自己怀念的部分，但不必把这张牌当成关系已经结束的证明。再看看自己仍能从对方或其他地方获得什么关怀，并考虑一次坦诚的沟通，或设下一条当下能支持自己的界限。"},"study":{"h":"工作或学习受挫之后","t":"先给自己一点时间承认失望，再写下这次挫折改变了什么、没有改变什么。找出一项仍能发挥的能力、一个可以联系的人，或一件眼下能做的任务。这样有助于你回应实际情况，而不让一次结果定义全部努力。"},"career":{"h":"抽到逆位时","t":"如果抽到逆位，可以留意自己何时又回到同一个痛苦念头。写下希望当时有所不同的地方，再补上一项此刻能带来安慰或支持的事。你不必逼自己得出结论，可以先选一个让今天更容易度过的小行动。"},"wealth":{"h":"综合提示","t":"圣杯五常与哀伤，以及为仍然拥有的事物留出空间有关。它并不是要你否认痛苦，也不要求你还没准备好就向前走。它可以提醒你承认失去，同时温和地留意身边仍可依靠的人、资源或日常习惯。"},"next":"在纸上分成两栏，写下“我正在哀悼的事”和“我仍能依靠的事”。每栏各写一条真实的内容，再选一件今天可以做的小事，照顾其中一栏。"},{"n":41,"name":"圣杯六","img":"Cups06.jpg","intro":"圣杯六常让人留意记忆、熟悉感，以及过去的经历如何影响现在。它可以邀请你珍惜曾经重要的事，但不必认定过去更简单或更美好。你可以借这张牌看看，哪些特质值得带进眼前的关系与日常。","love":{"h":"感情问题","t":"过去亲密的记忆可能影响你现在的期待。试着分清自己怀念的是什么，以及这段关系此刻实际是什么样子。说出一种你珍视的善意，再想想如何在尊重双方当下界限的前提下表达或讨论它。"},"study":{"h":"家人或旧友","t":"熟悉的关系可能令人安心，即使彼此都已改变。留意自己是在认识对方现在的样子，还是主要通过共同经历看待对方。一次简单的问候，并给彼此留下诚实回应的空间，有助于重新了解当下的彼此。"},"career":{"h":"抽到逆位时","t":"如果你总在拿现在和过去比较，可以分别写下当时真正支持你的部分，以及其中困难或不同之处，让回忆更完整。接着看看眼前有哪些联结或邀约值得回应，不必强求特定结果。"},"wealth":{"h":"综合提示","t":"圣杯六常让人留意记忆、熟悉感，以及过去的经历如何影响现在。它可以邀请你珍惜曾经重要的事，但不必认定过去更简单或更美好。你可以借这张牌看看，哪些特质值得带进眼前的关系与日常。"},"next":"从一段记忆中挑出一种你珍视的特质，例如慷慨或玩心，再想一个当下可以实践的小行动。做完后留意自己的感受，不必预设别人会如何回应。"},{"n":42,"name":"圣杯七","img":"Cups07.jpg","intro":"圣杯七常出现在多种可能同时吸引你注意的时候。生动的想法值得探索，但想象并不等于证据。这张牌可以帮助你说清自己想要什么，确认现实中有哪些条件，再做出选择；不必等到每个选项都显得完美才行动。","love":{"h":"感情问题","t":"当吸引力或可能性很强时，试着分开已观察到的事实与自己的期待。写下一次具体互动、一个个人推测，以及一个可以直接询问的问题。这样能让解读回到你的需要和边界，而不是把牌当作判断对方感受的证据。"},"study":{"h":"工作或学习选项","t":"如果有几条路都很吸引人，不妨比较它们日常需要付出的努力，而不只看想象中的好处。确认截止时间、所需技能、时间安排和可获得的支持。先聊一聊或做个小尝试，能让你在投入更多之前获得实际信息。"},"career":{"h":"迟迟无法做决定","t":"留意自己是在收集有用信息，还是在等待所有疑虑消失。给自己设一个重新评估选项的日期，说清最重要的条件，再选一个可行的小步骤。采取行动可以帮助你积累经验，并不代表做出无法撤回的承诺。"},"wealth":{"h":"综合提示","t":"圣杯七常出现在多种可能同时吸引你注意的时候。生动的想法值得探索，但想象并不等于证据。这张牌可以帮助你说清自己想要什么，确认现实中有哪些条件，再做出选择；不必等到每个选项都显得完美才"},"next":"列出正在考虑的选项，再标出哪些是已知事实、哪些是推测，以及什么对你最重要。选一个能在现实中检验首选方案的小行动。"},{"n":43,"name":"圣杯八","img":"Cups08.jpg","intro":"当一件曾经很有意义的事需要重新审视时，圣杯八可以成为一个反思提示。它并不意味着离开才是唯一诚实的选择；你可以借此留意仍然重要的事、已经发生的变化，以及是否存在不同的参与方式。","love":{"h":"感情关系","t":"留意这段关系中哪些部分让你感到彼此投入，哪些部分让你觉得不被看见或逐渐疲惫。在下结论前，先说清一项尚未表达的需要，并考虑一次坦诚的沟通能否帮助你了解选择空间。"},"study":{"h":"工作或学习","t":"如果眼下的道路不再那么吸引你，试着分辨这是暂时疲惫，还是长期的不合适。列出仍能支持你成长或身心状态的部分、持续消耗你的因素，以及一个可以先尝试的小调整。"},"career":{"h":"抽到逆位时","t":"看看舒适感、责任感或对未知的担忧是否正在左右选择。写下如果不受这些压力影响，你会倾向怎样选择；再将答案与现实需求和责任放在一起考量。"},"wealth":{"h":"综合提示","t":"当一件曾经很有意义的事需要重新审视时，圣杯八可以成为一个反思提示。它并不意味着离开才是唯一诚实的选择；你可以借此留意仍然重要的事、已经发生的变化，以及是否存在不同的参与方式。"},"next":"分两栏写下你想继续投入的事，以及你觉得不再值得同等付出的事。本周从中选一项小行动，例如一次沟通、设定一条边界，或调整一个日常习惯。"},{"n":44,"name":"圣杯九","img":"Cups09.jpg","intro":"圣杯九常与享受、珍惜以及了解自己看重什么有关。与其把它当作心愿必定实现的保证，不如借它留意现有哪些事支持着你的状态，以及除了短暂的愉悦，你还想培养怎样的满足感。","love":{"h":"感情问题","t":"留意哪些相处时刻让你感到被理解、自在，而不只关注看起来特别的举动。你可以说出一件感激的事，以及一个还未表达的需要。这张牌无法证明对方的感受，了解彼此仍要依靠沟通和持续的行动。"},"study":{"h":"达成一个目标之后","t":"完成任务或抵达一个阶段目标后，先花点时间看看哪些地方做得不错，再设定下一个目标。想想你追求的奖励是否符合自己的优先事项，还是主要为了获得认可。简单回顾付出、收获与休息，也能让成就更有实感。"},"career":{"h":"抽到逆位时","t":"如果舒适或享乐正变成回避不安的方式，可以先停一停，不急着用新的消遣盖过去。试着说出自己的情绪，留意什么情境会引发它，再选一个直接的回应，例如寻求支持或处理一件尚未完成的小事。"},"wealth":{"h":"综合提示","t":"圣杯九常与享受、珍惜以及了解自己看重什么有关。与其把它当作心愿必定实现的保证，不如借它留意现有哪些事支持着你的状态，以及除了短暂的愉悦，你还想培养怎样的满足感。"},"next":"设定五分钟计时，写下最近三件让你真心感到满足的时刻，也包括日常小事。在每件事旁写明它为何重要，再选一种能在本周为这种感受留出空间的小做法。"},{"n":45,"name":"圣杯十","img":"Cups10.jpg","intro":"圣杯十常让人关注那些让自己感到被接纳的关系与共同空间。它可以引导你思考，日常生活中的联结如何持续，而不只是停留在理想化的幸福图景里。借由这张牌，留意哪些关系滋养着你，以及一场坦诚的小对话能否带来帮助。","love":{"h":"友谊或社群关系","t":"看看彼此是否都能给予和接受支持，比较安静的人是否也有参与的空间。一句邀请、一条后续问候，或一项具体的帮忙，都能增进联结，而不必要求任何人总是表现得开心或隐藏难受。"},"study":{"h":"家庭或共同居住","t":"留意影响共同生活的日常安排：谁会主动关心彼此、承担实际事务，又是谁有机会表达想法。与其追求完美的相处氛围，不如说出一件能让日常生活对大家更体贴的小改变。"},"career":{"h":"抽到逆位时","t":"如果维持表面和睦让人费力，可以留意大家避而不谈的事，以及反复出现的相处模式。找一个平静、具体的切入点开启讨论，试着听见彼此的需要，不必指望一次谈话就解决所有问题。"},"wealth":{"h":"综合提示","t":"圣杯十常让人关注那些让自己感到被接纳的关系与共同空间。它可以引导你思考，日常生活中的联结如何持续，而不只是停留在理想化的幸福图景里。借由这张牌，留意哪些关系滋养着你，以及一场坦诚的"},"next":"写下一位你希望相处得更自在的人，或一个你想融入的群体。再写下一件本周可以做到的具体关怀，并记下需要什么边界或支持，才能让这件事持续下去。"},{"n":46,"name":"圣杯侍从","img":"Cups11.jpg","intro":"圣杯侍从常与好奇、想象力和对细微感受的留意有关。它可以邀请你认真探索一个不寻常的想法，但不必把每种感受都当成事实。借这张牌留意什么引起了你的兴趣，再决定是否要把它付诸实践。","love":{"h":"感情问题","t":"与其猜测某个举动代表什么，不如带着好奇开启一次清楚、没有压力的对话。留意自己的感受是否有所变化，说出一件你想了解的事，也给对方机会用自己的方式回应。"},"study":{"h":"某种感觉显得很迫切时","t":"如果一条温柔的信息或突然冒出的灵感显得格外重要，可以先暂停行动。把原话或想法记下来，分清哪些是你实际观察到的，哪些是自己的推断；等心情平稳后再回头看看，再决定是否需要回应或做个小尝试。"},"career":{"h":"创意项目","t":"先用小规模尝试来检验不寻常的想法，不必急着判断它是否可行。可以画个草图、写一小段初稿，或定时尝试一种方法。结束后记下学到了什么，以及要做得更完整还需要哪些资源。"},"wealth":{"h":"综合提示","t":"圣杯侍从常与好奇、想象力和对细微感受的留意有关。它可以邀请你认真探索一个不寻常的想法，但不必把每种感受都当成事实。借这张牌留意什么引起了你的兴趣，再决定是否要把它付诸实践。"},"next":"设定十分钟，把你一直搁置的不寻常想法写下来或画出来。圈出其中一部分，看看这周能否试试，再选一种简单、花费不高的方式来验证它。"},{"n":47,"name":"圣杯骑士","img":"Cups12.jpg","intro":"圣杯骑士常与情感表达、想象力以及带着心意发出的邀请有关。这张牌可以让你留意情感是如何传达的，同时也提醒你看看：一个动人的想法，是否有持续、可观察的行动作为支撑。","love":{"h":"表达关系中的心意","t":"发出真挚的信息或邀请前，先想清楚自己确实愿意给予什么。让表达具体，也给对方空间按自己的方式回应；如果做出了承诺，记得用行动兑现。"},"study":{"h":"发展一个创意","t":"吸引人的构想能为项目带来动力，但仍需要一个可执行的形状。写下第一件小任务、能投入的时间，以及决定是否扩大计划前还需要了解的事。"},"career":{"h":"抽到逆位时","t":"如果话语听起来比实际行动更漂亮，不妨先暂停，不急着许诺或接受承诺。说清楚哪些部分还不确定，询问具体细节，并留意后续行动是否与说法相符。"},"wealth":{"h":"综合提示","t":"圣杯骑士常与情感表达、想象力以及带着心意发出的邀请有关。这张牌可以让你留意情感是如何传达的，同时也提醒你看看：一个动人的想法，是否有持续、可观察的行动作为支撑。"},"next":"从正在考虑的一种表达或创意中选一项，写下你的意图、能体现它的一件行动，以及现实中可以完成这件事的时间。把计划控制在自己做得到的范围内。"},{"n":48,"name":"圣杯王后","img":"Cups13.jpg","intro":"圣杯王后常与细腻的情感觉察、慈悲心以及倾听内在感受有关。用于反思时，这张牌可以帮助你同时看见自己的感受与他人的需要，不把同理心变成必须承担一切或替别人做决定的责任。","love":{"h":"亲密关系中","t":"留意彼此是否都在倾听，还是情绪上的付出几乎落在你一个人身上。用清楚的话表达一项需要，并商量一种做得到的沟通方式，不必把解决对方所有感受当成自己的任务。"},"study":{"h":"工作或学习中","t":"同理心能帮助你察觉团队的反应，但不代表你要为每个人的情绪负责。答应额外帮忙前，先看看自己的时间和精力，再明确说出自己实际能提供什么。"},"career":{"h":"支持他人后感到疲惫","t":"在回复或答应更多事情前，先停一停。写下自己的感受、对方实际提出的请求，以及一条可以温和表达的界限。这有助于分清关心与替对方承担。"},"wealth":{"h":"综合提示","t":"圣杯王后常与细腻的情感觉察、慈悲心以及倾听内在感受有关。用于反思时，这张牌可以帮助你同时看见自己的感受与他人的需要，不把同理心变成必须承担一切或替别人做决定的责任。"},"next":"花五分钟画出两栏，分别写上“我的感受”和“对方需要承担的部分”。各写下一件眼前的烦心事，再拟一句温和的话，说明你能提供什么支持，以及需要在哪里停下。"},{"n":49,"name":"圣杯国王","img":"Cups14.jpg","intro":"圣杯国王常被解读为情绪上的沉稳：即使感受强烈，也能留在当下，不让情绪替自己做所有决定。这张牌邀请你审慎回应，而非疏离情感；也提醒你留意，平静是真正的从容，还是把重要感受藏了起来。","love":{"h":"发生意见冲突时","t":"回应之前，先说清自己正在感受什么，以及希望谈话达到什么目的。听对方实际说了什么，而不是猜测对方的意图。平和的语气能为坦诚留出空间，但不代表你必须隐瞒自己的界限。"},"study":{"h":"抽到逆位时","t":"留意自己是否一直回避直接沟通，或让私下的情绪影响选择。写下这种感受、可能的触发原因，以及哪些是你能确认的事实。然后决定要表达、设定界限，还是等自己能清楚回应时再行动。"},"career":{"h":"工作或团队协作中","t":"气氛紧张时，先把实际问题与周围的情绪分开。说明你观察到的情况、需要厘清的事项，以及一个可行的下一步。这样能让你参与解决问题，而不必负责照顾所有人的情绪。"},"wealth":{"h":"综合提示","t":"圣杯国王常被解读为情绪上的沉稳：即使感受强烈，也能留在当下，不让情绪替自己做所有决定。这张牌邀请你审慎回应，而非疏离情感；也提醒你留意，平静是真正的从容，还是把重要感受藏了起来。"},"next":"花五分钟写下一个尚未表达的感受、它可能因何而起，以及你希望接下来发生什么。再想好一句清晰而尊重彼此的话，用来表达这份感受。"},{"n":50,"name":"宝剑一","img":"Swords01.jpg","intro":"宝剑一可以让你留意自己如何形成并表达一个想法。它邀请你分清亲眼观察到的事与自己的推测，再考虑说出这些话会怎样影响相关的人。可以把它的主题当作反思提示，而不是某种解读必然正确的证明。","love":{"h":"一场关系中的沟通","t":"提出难谈的话题前，先写下你观察到的具体言行，以及它们带给你的影响。表达这些细节时避免替对方揣测动机，也留出空间听听对方的看法。"},"study":{"h":"工作或学习","t":"如果一个想法对你很重要，就让别人更容易判断它是否站得住脚。说明问题、呈现支持你观点的信息，并欢迎提问。先写一份简短提纲或草稿，有助于发现遗漏。"},"career":{"h":"抽到逆位时","t":"如果信息被误解，先别急着发出更尖锐的回应。确认对方实际听到了什么，一次澄清一个重点；如果交流开始紧张，也可以换一种更平和的沟通方式。"},"wealth":{"h":"综合提示","t":"宝剑一可以让你留意自己如何形成并表达一个想法。它邀请你分清亲眼观察到的事与自己的推测，再考虑说出这些话会怎样影响相关的人。可以把它的主题当作反思提示，而不是某种解读必然正确的证明。"},"next":"用一句话描述一件事，只写可以核实的细节。再用第二句话写下你想提出的问题或想表达的内容。决定是否分享之前，先重新读一遍。"},{"n":51,"name":"宝剑二","img":"Swords02.jpg","intro":"宝剑二可以让你留意一个难以面对的选择。它不会替你做决定，而是邀请你分辨已知的信息、内心的感受，以及自己可能正在回避的部分。把这些线索逐一理清，或许能帮助你更审慎地迈出下一步。","love":{"h":"一场关系中的沟通","t":"如果你一直推迟一场谈话，可以先写下希望弄清的事，以及需要表达的感受。试着区分对方实际说过或做过什么，以及你担心其中有什么含义。你可以选择一个平静的时机直接询问。"},"study":{"h":"工作或学习上的选择","t":"当两个选项难以比较时，分别列出它们在时间、支持、责任和学习机会上的实际要求。找出一个可以先核实的未知信息，避免只凭压力或猜测做决定。"},"career":{"h":"抽到逆位时","t":"如果新情况或强烈情绪让事情更难处理，先别把紧迫感当成清晰判断。记下发生了哪些变化，核实重要信息，再决定是否需要沟通，或给自己一点思考时间。"},"wealth":{"h":"综合提示","t":"宝剑二可以让你留意一个难以面对的选择。它不会替你做决定，而是邀请你分辨已知的信息、内心的感受，以及自己可能正在回避的部分。把这些线索逐一理清，或许能帮助你更审慎地迈出下一步。"},"next":"把眼前的选项分成两栏。每栏写下一项已知事实、一份顾虑和一个待确认的问题。选一个今天就能查清的问题，不必因此逼自己立刻做出最终决定。"},{"n":52,"name":"宝剑三","img":"Swords03.jpg","intro":"宝剑三常被解读为与痛苦、坦诚看见现实和释怀有关。它不能告诉你另一个人的感受，也不能决定接下来会发生什么。用于自我反思时，它可以帮助你说清伤痛、辨认已知事实，并按照自己的节奏回应。","love":{"h":"感情问题","t":"这张牌不能说明对方在想什么，也不能证明一段关系会不会结束。先关注实际说过的话和做过的事。如果某件事伤到了你，可以记下当时发生了什么、对你的影响，以及你想表达什么，不必预设对方会如何回应。"},"study":{"h":"工作或学习遇到挫折","t":"试着把具体挫折与对自己的整体评价分开。记下哪些反馈明确且有用，再找出一位能提供帮助的人或一项可用资源。给自己一点时间，别急着把失望变成对自己的定论。"},"career":{"h":"抽到逆位时","t":"想想是否有重要的感受或事实一直没有说出口。可以先在心里或纸上为它命名，再判断一场谈话是否安全且有帮助。你不必一次全盘托出；先选择一个合适的边界和能够做到的小步骤。"},"wealth":{"h":"综合提示","t":"宝剑三常被解读为与痛苦、坦诚看见现实和释怀有关。它不能告诉你另一个人的感受，也不能决定接下来会发生什么。用于自我反思时，它可以帮助你说清伤痛、辨认已知事实，并按照自己的节奏回应。"},"next":"设定五分钟计时，随手写下让你难受的事，不必修改，也不必立刻解释它的意义。圈出一句最贴近真实感受的话，再决定先留给自己、分享给信任的人，或过些时候再读。"},{"n":53,"name":"宝剑四","img":"Swords04.jpg","intro":"宝剑四常被解读为紧绷或思绪密集之后，有意停下来歇一歇。它可以提醒你，在承担下一项任务前为恢复留出空间，而不必把休息当作必须先完成所有事情才能得到的奖励。也可以借此看看，日常生活里怎样才算真正安静片刻。","love":{"h":"关系中的紧张之后","t":"如果对话已经变得激烈，可以考虑约定一段明确的暂停时间，而不是急着当场解决。告诉对方你何时愿意继续谈，并利用这段间隔分清自己想表达什么，以及还需要了解什么。"},"study":{"h":"繁忙的工作或学习之后","t":"留意自己是否不断切换任务，却没有时间消化已经完成的部分。试试短暂离开屏幕，回来后再选出一个优先事项。暂停可以成为可持续安排的一部分，并不代表你落后了。"},"career":{"h":"很难慢下来的时候","t":"看看自己是否总用小习惯填满安静的时刻，比如查看消息或再加一项任务。选一小段时间，不安排任何事情。如果这让你不自在，先留意浮现的念头或期待，再决定接下来要做什么。"},"wealth":{"h":"综合提示","t":"宝剑四常被解读为紧绷或思绪密集之后，有意停下来歇一歇。它可以提醒你，在承担下一项任务前为恢复留出空间，而不必把休息当作必须先完成所有事情才能得到的奖励。也可以借此看看，日常生活里怎"},"next":"今天安排十分钟暂停，并把手机放到够不着的地方。先写下休息后要继续处理的任务，再安静呼吸或坐一会儿，不必给这段时间添加新的目标。"},{"n":54,"name":"宝剑五","img":"Swords05.jpg","intro":"宝剑五可以让人留意紧张关系、彼此竞争的优先事项，以及人们处理分歧的方式带来的影响。它并不裁定谁对谁错。用于反思时，这张牌可以帮助你看清什么比争辩输赢更重要，以及自己愿意参与怎样的交流。","love":{"h":"关系中的分歧","t":"留意这场对话是在帮助双方理解问题，还是渐渐变成了计较输赢。你可以说清具体的分歧，听听彼此真正看重的是什么；如果有人已经难以尊重地表达，不妨先暂停交流。"},"study":{"h":"工作或学习中的冲突","t":"把眼前任务和人际摩擦分开处理。写下需要解决的事项、尚不明确的证据或预期，以及需要参与沟通的人。一份清晰的情况梳理，能让后续讨论更聚焦，也更公平。"},"career":{"h":"抽到逆位时","t":"重新谈起一场难以处理的交流前，可以先想想自己能够坦诚承担什么，还有哪些地方需要说清楚。简短道歉、表达界限，或约定稍后再谈，可能比一次解决所有分歧更实际。"},"wealth":{"h":"综合提示","t":"宝剑五可以让人留意紧张关系、彼此竞争的优先事项，以及人们处理分歧的方式带来的影响。它并不裁定谁对谁错。用于反思时，这张牌可以帮助你看清什么比争辩输赢更重要，以及自己愿意参与怎样的交"},"next":"写下争议的核心、你想守住的价值，以及继续按当前方式争论的一项代价。然后选一个小行动，既能回应问题，也不违背这项价值。"},{"n":55,"name":"宝剑六","img":"Swords06.jpg","intro":"宝剑六常被解读为从紧张处境驶向更安稳状态的一段路。它可以提醒你留意哪些支持能让变化更容易承受，也承认离开一段艰难时期需要时间。这张牌不保证旅程轻松，而是邀请你想想，什么值得带在身边，什么可以暂时放下。","love":{"h":"应对关系中的难题","t":"在关系问题中，这张牌可以让你留意彼此如何一起走过一场难谈的对话或一段变化期。看看双方是否都有表达的空间，现实中有哪些支持可用，以及哪些旧争论或期待已无助于看清当下。"},"study":{"h":"工作或学业上的变动","t":"在工作或学习中，想想清楚的交接、减轻一些任务，或可信任之人的帮助，能否让变化更好应对。列出必须完成的事、可以稍后处理的事，以及迈出下一步前可以寻求的一项资源。"},"career":{"h":"抽到逆位时","t":"借这张牌看看变化为何让你觉得复杂，但别把不舒服直接当作该留下或离开的证据。写下一项尚未解决的顾虑，分清哪些部分在自己掌控之中，再判断谈一谈、设立边界或暂缓片刻是否有帮助。"},"wealth":{"h":"综合提示","t":"宝剑六常被解读为从紧张处境驶向更安稳状态的一段路。它可以提醒你留意哪些支持能让变化更容易承受，也承认离开一段艰难时期需要时间。这张牌不保证旅程轻松，而是邀请你想想，什么值得带在身边"},"next":"画两栏，分别写上“留在身边”和“暂且放下”，每栏列出三件事。然后选一件能让接下来几天更轻松的小事去做，休息之后再回来看这张清单。"},{"n":56,"name":"宝剑七","img":"Swords07.jpg","intro":"宝剑七常与策略、隐私，以及人在难以直接表达时所做的选择有关。它可以帮助你分辨，暂时低调处理是在守护合理的边界，还是让情况变得含糊。这张牌不能说明别人心里怎么想；不妨借它厘清自己的做法与限度。","love":{"h":"感情问题","t":"如果你有所保留，先分辨那是私人信息、个人边界，还是对方需要了解才能做出知情选择的事情。你可以先准备一场平静坦诚的对话，不必透露让自己感到不安全的内容。把重点放在如何清楚、尊重地表达上。"},"study":{"h":"抽到逆位时","t":"如果有所隐瞒已经影响到别人，可以先具体说明自己的行为及其影响，不必急着找借口。再想想哪些地方能够补救、谁需要知道相关信息，以及什么边界或流程有助于避免重演。承担责任，不等于把自己看得一无是处。"},"career":{"h":"工作或团队合作","t":"处理敏感事务时，可以清楚记录已知信息、已有约定和仍不确定之处。谨慎处理有助于保护应有的保密范围，但也要避免因分工不明或遗漏细节，给同事带来额外工作。"},"wealth":{"h":"综合提示","t":"宝剑七常与策略、隐私，以及人在难以直接表达时所做的选择有关。它可以帮助你分辨，暂时低调处理是在守护合理的边界，还是让情况变得含糊。这张牌不能说明别人心里怎么想；不妨借它厘清自己的做"},"next":"写下一件你暂时不想公开的事，并说明原因。再想想是否有人需要你作出解释，然后拟一句可以用来开启对话的话，同时保留自己的边界。"},{"n":57,"name":"宝剑八","img":"Swords08.jpg","intro":"宝剑八可以提醒你分辨：哪些事情确实限制了自己，哪些感觉固定不变，可能源于恐惧、习惯或信息不足。它不会替你决定该怎么做。一次有帮助的解读，可以让你说清限制是什么，用眼前的事实核对，并找出仍能做出的小选择。","love":{"h":"关系中的一次谈话","t":"如果觉得某次谈话难以开口，可以分别列出对方实际说过的话，以及自己正在预想的内容。再挑一个清楚、压力较小的问题或界限表达出来。这张牌不能证明对方的意图；你可以借此留意，哪些假设正在缩窄自己的选择。"},"study":{"h":"工作或学习遇到阻碍","t":"如果一项任务似乎卡住了，先找出具体缺少的要求、时间或资源。再记下一个可能帮你厘清情况的人、一份资料或一个小实验。这样能把笼统的受阻感变成一个可处理的具体问题，不必立刻做出重大改变。"},"career":{"h":"抽到逆位时","t":"如果你已开始看到其他可能，却仍不太敢行动，可以列出几个选项，并为每个选项想一个最小、稳妥的尝试。如果处境确有现实限制，就直接写明，并寻求合适的支持，不必因为感到受困而责怪自己。"},"wealth":{"h":"综合提示","t":"宝剑八可以提醒你分辨：哪些事情确实限制了自己，哪些感觉固定不变，可能源于恐惧、习惯或信息不足。它不会替你决定该怎么做。一次有帮助的解读，可以让你说清限制是什么，用眼前的事实核对，并"},"next":"画两栏，分别写上“可以核实的事实”和“我正在做的假设”。每栏写一项，再选一个小行动，帮助你弄清某个假设，同时避免不必要的风险。"},{"n":58,"name":"宝剑九","img":"Swords09.jpg","intro":"宝剑九常与独处时不断加重的担忧有关，尤其是思绪反复打转的时候。它并不能证明你害怕的事情正在发生，而是可以邀请你停下来核对已知信息，并想想什么样的支持或安抚能帮助你面对当下。","love":{"h":"担心一段关系","t":"如果一场对话或一段沉默让你不安，可以把对方实际说过或做过的事，与自己担心它代表什么分开记录。合适的话，试着提出清楚、具体的问题，而不是把猜测当作证据。"},"study":{"h":"工作或学习压力","t":"面对要求较多的任务，反复设想可能出错的地方，往往会让它显得更难。写下眼前最具体的要求、仍缺少哪些信息，以及可以向谁请教实际问题。"},"career":{"h":"睡前的担忧","t":"如果准备休息时思绪仍在打转，可以把烦心事写下来，并标注哪些是事实、哪些是可能性、哪些尚不清楚。选一件明天能处理的小事，其余暂时留待之后。"},"wealth":{"h":"综合提示","t":"宝剑九常与独处时不断加重的担忧有关，尤其是思绪反复打转的时候。它并不能证明你害怕的事情正在发生，而是可以邀请你停下来核对已知信息，并想想什么样的支持或安抚能帮助你面对当下。"},"next":"画两栏，分别写下“我害怕的事”和“我能观察到的事”。各填一项，再写一个有助于分清两者的实际小步骤。你不必现在就解决所有不确定。"},{"n":59,"name":"宝剑十","img":"Swords10.jpg","intro":"宝剑十常被解读为精疲力竭、某个阶段走到尽头，或提醒你不必独自承担一场挣扎。它并没有规定接下来会发生什么。作为反思提示，它可以帮助你看清什么已经走到尽头、有哪些支持可用，并按自己的节奏为恢复留出空间。","love":{"h":"关系中反复出现冲突","t":"如果一段关系里冲突反复发生，这张牌可以邀请你分辨：眼前是一次困难，还是一种已难以维持的相处模式。留意实际发生了哪些变化、哪些问题仍未解决，以及平静沟通或寻求外部支持是否有帮助。"},"study":{"h":"工作或学习让人难以承受","t":"留意工作或学习中哪些投入已难以持续。列出可以完成、暂缓或交接的事项，再选定一条实际可行的界限。休息可以是审慎应对的一部分，并不代表你失败了。"},"career":{"h":"抽到逆位时","t":"逆位时，这张牌可能映照出你还难以接受一场挣扎已经变化或结束。与其逼自己马上准备好，不如找出一个会让你反复想起此事的提醒或习惯，再用一个小行动承认经历，并把注意力带回当下的需要。"},"wealth":{"h":"综合提示","t":"宝剑十常被解读为精疲力竭、某个阶段走到尽头，或提醒你不必独自承担一场挣扎。它并没有规定接下来会发生什么。作为反思提示，它可以帮助你看清什么已经走到尽头、有哪些支持可用，并按自己的节"},"next":"写下一场你不必继续独自承担的挣扎，再列出一件可以收尾的事、一位可以求助的人，以及一项明天能安排的恢复精力的活动。"},{"n":60,"name":"宝剑侍从","img":"Swords11.jpg","intro":"宝剑侍从常提醒人保持好奇、留意细节，并检验自己以为已经知道的事。它可以帮助你更清楚地沟通，但匆忙下结论仍然只是下结论。借由这张牌，你可以区分证据与解读，并想想什么问题或对话能让处境更明朗。","love":{"h":"核实一条消息","t":"转述听来的消息前，先追溯来源，并查看哪些细节可以核实。分清哪些是自己亲自了解的，哪些只是别人的推断。如果信息不完整，就坦白说明，不要用猜测补上空缺。"},"study":{"h":"沟通气氛紧张时","t":"尖锐的回应可能让彼此更难听懂对方。回复前，先写下你真正想弄清的具体问题，再就事提问，不替对方揣测动机。留意回答是否回应了问题，或仍有重要之处没有说清。"},"career":{"h":"为一个选择搜集信息","t":"好奇心能帮助你找到有用资料，但不断搜集细节不一定代表有所进展。先明确要回答的问题，比较可靠来源，并记下哪些证据可能改变你的看法。之后再判断自己还需要了解什么。"},"wealth":{"h":"综合提示","t":"宝剑侍从常提醒人保持好奇、留意细节，并检验自己以为已经知道的事。它可以帮助你更清楚地沟通，但匆忙下结论仍然只是下结论。借由这张牌，你可以区分证据与解读，并想想什么问题或对话能让处境"},"next":"写下一项自己正在抱持的假设，再列出支持它和质疑它的依据，以及一个能带来新证据的来源或直接问题。核实这一点后，再考虑如何行动。"},{"n":61,"name":"宝剑骑士","img":"Swords12.jpg","intro":"宝剑骑士常让人留意一个想法变成行动的速度。这张牌可以提示你明确重点、集中精力，也提醒你观察步调过快时可能忽略了什么。借此检查行动依据、精力是否充足，以及自己的表达会给他人带来怎样的影响。","love":{"h":"一场关系中的对话","t":"谈一个棘手话题前，先想清楚希望对方理解什么。尽量用具体事例表达，也给对方回应的空间；留意自己的措辞是在促成交流，还是让对话难以继续。"},"study":{"h":"工作或学习的期限","t":"先选出最重要的任务，并在开始前明确怎样才算完成。估算自己实际拥有的时间和精力，再把工作拆成可以检查的小步骤，不要只靠一时的冲劲。"},"career":{"h":"需要尽快做决定","t":"把已有事实和仍需确认的信息分开。如果可以稍后决定，就留一段时间补齐资料；如果不能等待，先想好一项能让后续调整更容易的保障措施。"},"wealth":{"h":"综合提示","t":"宝剑骑士常让人留意一个想法变成行动的速度。这张牌可以提示你明确重点、集中精力，也提醒你观察步调过快时可能忽略了什么。借此检查行动依据、精力是否充足，以及自己的表达会给他人带来怎样的"},"next":"设一个五分钟计时器，写下准备采取的行动、支持它的事实，以及一项可能改变计划的因素。然后先做最小且有用的一步，再看看自己的节奏是否需要调整。"},{"n":62,"name":"宝剑王后","img":"Swords13.jpg","intro":"宝剑王后常与洞察、直率表达和尊重相关。她可以提醒你清楚说出自己的观察，同时顾及具体情境与他人的处境。清晰的表达不必终止对话；它也能帮助你更好地理解问题，并为倾听留出空间。","love":{"h":"感情中的一次沟通","t":"开口前，先分清自己观察到的事实，以及对此作出的解释。直接说出在意之处，再给对方回应的空间。尊重而坦率的表达，能让难谈的话题更清楚，而不必变成对人的定论。"},"study":{"h":"工作或学习中的反馈","t":"尽量用具体例子代替笼统评价。说明想讨论的任务、行为或要求，并询问怎样做会更明确。这样既能保留对成果的要求，也能让反馈指向实际改进，而非针对个人。"},"career":{"h":"抽到逆位时","t":"如果你发现自己反复回想受伤之处，或用绝对的判断看待某个人，先暂停，不急着依据这个想法行动。写下一种其他可能的解释，或提出一个中性的澄清问题。"},"wealth":{"h":"综合提示","t":"宝剑王后常与洞察、直率表达和尊重相关。她可以提醒你清楚说出自己的观察，同时顾及具体情境与他人的处境。清晰的表达不必终止对话；它也能帮助你更好地理解问题，并为倾听留出空间。"},"next":"用一句不带责备的话描述眼前的情况，再补上一句说明自己需要什么或想了解什么。读一遍后，删去给人贴标签的词，只留下对行为的描述。"},{"n":63,"name":"宝剑国王","img":"Swords14.jpg","intro":"宝剑国王常提醒人谨慎作决定、说明自己的理由，并用同一套标准要求自己与他人。这张牌也能让人留意权威是如何被使用的。论据清楚固然重要，背景、倾听，以及言语对他人的影响也同样值得考虑。","love":{"h":"关系中的意见分歧","t":"试着分清实际发生的事与自己对它的解读。用具体例子说明你的顾虑，也给对方机会表达他的看法。清楚地表达有助于对话保持尊重，同时不必忽略自己的需要。"},"study":{"h":"带领一个团队","t":"在评价工作表现前，先让大家了解具体的期待。检查评估标准是否适用于每个人，也邀请团队成员谈谈决定会如何影响相关的人。标准清楚，也应当让人能够理解和讨论。"},"career":{"h":"为自己设定标准","t":"如果你正在权衡选择，可以写下想遵循的原则和已有事实，再想一项可能改变看法的背景信息。这样能帮助你立场坚定，同时避免把某个判断变成不加思考的定论。"},"wealth":{"h":"综合提示","t":"宝剑国王常提醒人谨慎作决定、说明自己的理由，并用同一套标准要求自己与他人。这张牌也能让人留意权威是如何被使用的。论据清楚固然重要，背景、倾听，以及言语对他人的影响也同样值得考虑。"},"next":"选一件正在处理的决定，写下你采用的标准、支持它的事实，以及尚未听到的一种相关看法。然后找一个小方法，在行动前核实这项看法。"},{"n":64,"name":"星币一","img":"Pents01.jpg","intro":"星币一常提醒人留意哪些想法有机会通过实际行动逐渐成形。它并不保证成功或安全感，而是邀请你看看自己现在能做些什么、已有哪些支持，以及持续投入能否让一个值得的目标慢慢落地。","love":{"h":"培养日常习惯","t":"新习惯若能融入真实的日常，更容易坚持。先选一个很小的行动，把它接在已有习惯之后，再留意重复起来容易或困难的原因。可以调整做法，不必因此责备自己。"},"study":{"h":"开始工作或学习项目","t":"把宽泛的目标拆成一项看得见的起步任务。确认手边已有的材料、时间或帮助，再设定一个适度的阶段目标，方便之后回顾。下一步越具体，进展就越容易判断。"},"career":{"h":"抽到逆位时","t":"如果计划显得不够稳，或注意力被许多事情分散，不妨先暂停，不要急着增加承诺。写下计划依赖哪些条件、哪些地方仍不明确，以及决定下一步前可以先查清的一件事。"},"wealth":{"h":"综合提示","t":"星币一常提醒人留意哪些想法有机会通过实际行动逐渐成形。它并不保证成功或安全感，而是邀请你看看自己现在能做些什么、已有哪些支持，以及持续投入能否让一个值得的目标慢慢落地。"},"next":"把一个实际目标写下来，再列出本周能做的最小行动。注明何时、在哪里行动，并选一天回顾过程中的发现。"},{"n":65,"name":"星币二","img":"Pents02.jpg","intro":"星币二可以让你留意同时维持生活多个部分运转所付出的心力。它并非要求你事事兼顾，而是邀请你看看此刻什么最需要关注、哪些事情可以稍后处理，以及当情况变化时，日常安排如何随之调整。","love":{"h":"在关系中分配时间","t":"忙碌的日程可能让相处也像一项待办任务。看看目前双方如何安排时间和实际责任，再提出一个能让共同生活更容易维持的小调整。尽量把话说具体，也为彼此的需要留出讨论空间。"},"study":{"h":"工作或学习","t":"如果几项任务都在争取你的注意力，写下各自的期限和下一步要做的事。看看哪些可以延期、分担或缩小范围。这样能让你更清楚地了解自己的工作量，再决定是否接下新的任务。"},"career":{"h":"安排忙碌的一周","t":"不要把日程表里的每个空档都填满，先标出不可或缺的安排，并为延误或休息留些余地。留意哪些计划可以调整。如果这一周已经太满，可以选择一件事延期或简化。"},"wealth":{"h":"综合提示","t":"星币二可以让你留意同时维持生活多个部分运转所付出的心力。它并非要求你事事兼顾，而是邀请你看看此刻什么最需要关注、哪些事情可以稍后处理，以及当情况变化时，日常安排如何随之调整。"},"next":"快速列出所有正在占用你注意力的事情，圈出今天最重要的两项，再选一件事延期、分担或缩小范围。看看这个调整会怎样影响你的日程。"},{"n":66,"name":"星币三","img":"Pents03.jpg","intro":"星币三常被解读为通过合作与熟练实践，让成果更加扎实。它可以提醒你重视自己的贡献，也留意身边人的经验。这张牌并不保证获得认可或成功，而是邀请你把期待说清楚，让有用的反馈参与到做事过程中。","love":{"h":"关系中的责任分担","t":"在一段关系里，关心若落实为具体行动，彼此的付出会更容易看见。留意双方各自承担了什么，说出一件你欣赏的事，再谈谈哪项任务或期待需要更明确的约定。"},"study":{"h":"工作或学习中的反馈","t":"工作或学习时，可以趁草稿、计划或技能还容易调整时征求意见。确认什么样的质量才算达标、谁需要审阅以及何时反馈。这样能让建议更具体，也方便你判断如何采用。"},"career":{"h":"团队项目中的分工不清","t":"如果团队项目让人觉得分担不均，可以列出各项任务和负责人，再确认如何同步进度、哪些决定需要共同讨论。这样有助于看清彼此期待的差异，而不必先假定有人不愿配合。"},"wealth":{"h":"综合提示","t":"星币三常被解读为通过合作与熟练实践，让成果更加扎实。它可以提醒你重视自己的贡献，也留意身边人的经验。这张牌并不保证获得认可或成功，而是邀请你把期待说清楚，让有用的反馈参与到做事过程"},"next":"选一项正在进行的工作，写下它的目的、需要达到的标准，以及一个想请教合作伙伴的问题。围绕这个问题征求反馈，再决定哪些内容保留，哪些需要调整。"},{"n":67,"name":"星币四","img":"Pents04.jpg","intro":"星币四常让人留意自己如何保护重要的东西，例如金钱、时间、精力或个人界限。它可以邀请你看看，现有的保护方式是在带来安稳，还是限制了有益的交流。牌面不会替你决定应该保留或分享什么。","love":{"h":"亲密关系中","t":"留意自己是否把计划、感受或责任管得太紧，以至于产生距离感。先说清楚一项对你很重要的界限，再考虑用低风险的小方式邀请合作，例如征求意见，或说明怎样做会让你更安心。"},"study":{"h":"抽到逆位时","t":"看看自己是否因为改变让人不舒服，才一直遵循某条规则或习惯。想想这条规则如今有哪些事实依据，以及怎样做一个小调整，既能尝试不同的方法，也不必放弃安全感。"},"career":{"h":"工作或共同项目","t":"如果你不太愿意交接任务或分享想法，先找出犹豫背后的具体顾虑。可以商定清楚的分工或沟通时间，再观察多一点合作是否让事情更顺利，同时保留真正重要的部分。"},"wealth":{"h":"综合提示","t":"星币四常让人留意自己如何保护重要的东西，例如金钱、时间、精力或个人界限。它可以邀请你看看，现有的保护方式是在带来安稳，还是限制了有益的交流。牌面不会替你决定应该保留或分享什么。"},"next":"写下一件你正在保护的事，以及它需要防范什么。然后记下一个小小的做法，让自己尝试分享、使用或稍微放松掌控，同时保留一项对你重要的界限。"},{"n":68,"name":"星币五","img":"Pents05.jpg","intro":"星币五可以让人留意生活中感到局促的时刻，尤其是与归属感、资源或求助有关的处境。它不能告诉你有哪些支持可用，也不能说明别人怎么想。可以把它当作一个提醒：看清眼下的难处，并想想有没有值得安心求助的人或服务。","love":{"h":"关系变得疏远","t":"如果你最近与某人少有联系，可以先说清自己想念哪种相处，而不是猜测对方能提供什么。发出简单明确的邀请，例如约通电话，或请对方陪你办一件事，有助于看清这段联结能否回应你的需要。"},"study":{"h":"工作或学习感到吃力","t":"如果独自应付任务或期限让你吃力，先列出具体障碍：时间不足、缺少工具、要求不清，或工作量太大。然后向信任的同事、老师或主管提出一项明确的请求。比起为自己的困难泛泛道歉，具体的请求更容易得到回应。"},"career":{"h":"寻找实际帮助","t":"如果开口求助让你觉得难为情，可以选一位你认为可靠的人或一个安心的服务渠道，并先想清楚需要什么。你可以请求陪伴、协助完成某件事，或询问有哪些支持可用；只需说明足以让对方理解请求的内容。"},"wealth":{"h":"综合提示","t":"星币五可以让人留意生活中感到局促的时刻，尤其是与归属感、资源或求助有关的处境。它不能告诉你有哪些支持可用，也不能说明别人怎么想。可以把它当作一个提醒：看清眼下的难处，并想想有没有值"},"next":"写下一项眼前的实际困难，以及什么样的帮助能让它更容易应对。再写下一位可以联系的人或一项服务，并拟好一段简短明确的请求，暂时不必发送。"},{"n":69,"name":"星币六","img":"Pents06.jpg","intro":"星币六常从日常的给予与接受来理解。它可以让你留意公平、慷慨，以及资源如何在彼此之间流动。与其急着判断一场交换是好是坏，不如借这张牌观察每个人付出了什么、需要什么，以及对这段安排有怎样的理解。","love":{"h":"接受他人的帮助","t":"如果有人提出帮助，可以先确认对方具体提供什么，以及是否期待你做出回报。你可以接受、婉拒，或先争取时间考虑。留意这项安排是否让你保有自主选择的空间，也说清楚哪些界限能让你安心接受。"},"study":{"h":"抽到逆位时","t":"如果一场交换让你感到不自在，可以分别列出付出了什么、得到了什么，以及附带了哪些条件。再考虑是否能重新协商、设定界限，或寻找其他支持来源。不要把感激当成必须放弃自主选择的欠债。"},"career":{"h":"工作或共同项目","t":"看看认可、时间、信息和实际协助是如何分配的。如果有人承担得更多，试着具体说出是哪项任务或贡献，而不只停留在不公平的感觉上。接着商量一个明确的调整，例如轮流负责某项事务，或把分工列清楚。"},"wealth":{"h":"综合提示","t":"星币六常从日常的给予与接受来理解。它可以让你留意公平、慷慨，以及资源如何在彼此之间流动。与其急着判断一场交换是好是坏，不如借这张牌观察每个人付出了什么、需要什么，以及对这段安排有怎"},"next":"选一场最近发生的交换，分两栏写下自己提供了什么、收到了什么。再补上注意到的期待或代价，并找出一项可以在下次交换前说清楚的小提醒或界限。"},{"n":70,"name":"星币七","img":"Pents07.jpg","intro":"星币七常被视为停下来看看已有成果的时刻。它提醒人保持耐心，但不只是被动等待：留意什么正在发展、什么仍需照料，以及目前的投入是否仍有助于实现目标。","love":{"h":"一段关系中","t":"留意日常中哪些行动在滋养这段关系，不要只依赖对未来的期待。想想彼此各自投入了什么、什么需要更多关注，以及一次平和的交谈能否让双方的期待更清楚。"},"study":{"h":"工作或学习中","t":"在增加工时或接下新任务之前，先回顾进度。把目前成果与原定目标比较，找出一个仍需加强的技能或环节，并决定何时再次检查进展。"},"career":{"h":"抽到逆位时","t":"如果等待让你感到烦躁，可以检查自己是否期待成果来得太快，或只是习惯性地继续投入。说清楚哪里不奏效，再对照最初的目标，在花费更多精力前调整计划中的一个部分。"},"wealth":{"h":"综合提示","t":"星币七常被视为停下来看看已有成果的时刻。它提醒人保持耐心，但不只是被动等待：留意什么正在发展、什么仍需照料，以及目前的投入是否仍有助于实现目标。"},"next":"写下一件你持续投入的事、一项实际可观察到的进展，以及一件仍需照料的事。为本周选一个小行动，并设定日期回顾结果。"},{"n":71,"name":"星币八","img":"Pents08.jpg","intro":"星币八常让人关注一项技能如何在日常练习中逐渐形成。它可以邀请你观察自己的过程：正在学什么，哪些步骤已经变成习惯，以及投入是否仍与自己在意的目标有关。进步不必毫无瑕疵，依然可以有意义。","love":{"h":"当日常练习变得乏味","t":"如果做着做着开始走神，先暂停，不必立刻加码投入。说清楚这项任务原本要帮助你学会什么或完成什么，再调整一个环节，例如设定明确的停止时间，或试试不同的方法。"},"study":{"h":"学习一项技能","t":"一次选定技能中的一个部分来练习，不必同时改进所有方面。练习后记下哪些地方变顺了、哪里卡住，以及下次准备做的一项调整。这样，练习就能留下有用的信息，而不只是累积时长。"},"career":{"h":"工作或学习中","t":"看看自己经常处理的一项任务，找出一个会影响质量的细节。可以请别人给出具体反馈，或将最近的成果与早期版本对照。简单回顾一下，有助于判断当前方法是否服务于目标，还是只是在照惯例完成。"},"wealth":{"h":"综合提示","t":"星币八常让人关注一项技能如何在日常练习中逐渐形成。它可以邀请你观察自己的过程：正在学什么，哪些步骤已经变成习惯，以及投入是否仍与自己在意的目标有关。进步不必毫无瑕疵，依然可以有意义"},"next":"下次练习结束后，写下一个观察、一项准备调整的地方，以及一个想继续探索的问题。记录保持简短，再用它来安排下一次练习。"},{"n":72,"name":"星币九","img":"Pents09.jpg","intro":"星币九常与自立、用心经营的舒适生活，以及欣赏自身付出有关。它可以邀请你留意哪些地方让自己感到自在，也提醒你看看，独立生活是否仍为人际联结与共同享受留有空间。","love":{"h":"留一些时间给自己","t":"独处可能让人恢复精力，但也可以留意它是否成了唯一的选择。回想过去一周：什么时候你享受独处，什么时候你在回避联系他人？如果符合自己的意愿，可以选择一种轻松、没有压力的联络方式。"},"study":{"h":"工作或学习的进展","t":"停下来，具体说出一项由持续努力培养出的技能或成果。是什么帮助你坚持下来？现在又有哪些过程值得欣赏？允许自己认可这份付出，不必让自我价值取决于持续高效。"},"career":{"h":"抽到逆位时","t":"如果你感到疏离，或对开销有些不安，可以先观察实际情况，而不是把牌当成定论。留意自己与人联系的频率，以及近期消费是否符合重视的事情。简单回顾这些模式，有助于厘清自己想调整什么。"},"wealth":{"h":"综合提示","t":"星币九常与自立、用心经营的舒适生活，以及欣赏自身付出有关。它可以邀请你留意哪些地方让自己感到自在，也提醒你看看，独立生活是否仍为人际联结与共同享受留有空间。"},"next":"留出十分钟安静写下：一件让你欣慰的付出、一种自己真心享受的舒适，以及一位你愿意邀请来分享这份快乐的人。是否分享由你决定，不必把它变成责任。"},{"n":73,"name":"星币十","img":"Pents10.jpg","intro":"星币十常让人关注塑造归属感的人际网络、习惯与知识。它可以邀请你看看哪些东西来自过去，哪些值得继续传下去，以及在更大的家庭或社群故事中，自己的价值观应占有什么位置。","love":{"h":"谈到家庭传统时","t":"选一项传统，留意参与其中的人能从中获得什么：联结、慰藉、责任感，或其他感受。想想由谁来决定如何延续，以及它是否仍适合相关的人。做些小调整，既能保留重要的部分，也能顾及不同需要。"},"study":{"h":"在工作或学习中分享经验","t":"想想一个团队长期积累了哪些经验，以及新加入的人是否容易了解这些知识。你可以整理一套实用流程、邀请成员分享经验，或询问哪些做法值得带进下一个项目。"},"career":{"h":"家庭期待让人感到沉重时","t":"分清哪些事是自己主动选择的，哪些事是觉得自己应该去做的。留意有哪些对话一直被搁置，再找出一件想清楚、尊重地表达的事。你可以珍视自己的成长背景，同时判断哪些期待仍适合现在的生活。"},"wealth":{"h":"综合提示","t":"星币十常让人关注塑造归属感的人际网络、习惯与知识。它可以邀请你看看哪些东西来自过去，哪些值得继续传下去，以及在更大的家庭或社群故事中，自己的价值观应占有什么位置。"},"next":"画两栏，分别写上“我想延续的”和“我想重新考虑的”。每栏写下一项家庭或社群习俗，再为其中一个选择写下一件本周可以实行的小行动。"},{"n":74,"name":"星币侍从","img":"Pents11.jpg","intro":"星币侍从可以提醒你，学习离不开耐心、练习和可执行的计划。与其急着证明自己的潜力，不如看看自己愿意持续钻研什么。无论是预算、课程还是动手技能，专注地投入都能让下一步更清楚。","love":{"h":"抽到逆位时","t":"如果计划越列越多，最初的任务却一直没开始，可以先缩小范围。写明下一步要做什么、需要多久，并安排到日程中。如果总是分心，就减少一个干扰，或请人帮忙提醒自己按计划行动。"},"study":{"h":"工作或学习","t":"挑出一个需要弄懂的主题，为进展设定一个小目标，例如完成一节课程，或用自己的话讲清一个概念。在增加更多任务前，先看看还有哪些地方不明白。这样能让精力真正用在理解上，而不只是让自己忙起来。"},"career":{"h":"综合提示","t":"星币侍从可以提醒你，学习离不开耐心、练习和可执行的计划。与其急着证明自己的潜力，不如看看自己愿意持续钻研什么。无论是预算、课程还是动手技能，专注地投入都能让下一步更清楚。"},"wealth":{"h":"检查一项金钱习惯","t":"可以借这张牌观察一项日常金钱习惯，但不必把它当成财务决策的依据。记录一周的支出，或看看某项固定开销，再写下自己想弄清楚的问题，然后再考虑是否调整习惯。"},"next":"选一项你一直拖着没学的实用内容，花十五分钟看一节入门课程或做个简单练习。然后记下一件学到的事，以及接下来想弄清的问题。"},{"n":75,"name":"星币骑士","img":"Pents12.jpg","intro":"星币骑士常让人留意日常付出如何一点点累积：履行承诺、核对细节，或重新回到手边的任务。重点不在速度，而在是否认真完成。在反思时，可以看看现有习惯是否仍服务于你的目标，以及哪里适合做一点调整。","love":{"h":"关系相处","t":"可靠可以体现在一次次具体行动中，不只是在言语承诺里。留意约定是否得到遵守、责任是否共同承担。如果日常相处显得乏味，可以明确说出一项希望改变的事情；耐心不应成为忽视自身需要的理由。"},"study":{"h":"工作或学习","t":"选择一项适合认真推进的任务，并在开始前说清楚怎样才算完成。仔细核对关键细节；如果要求不够明确，就寻求反馈。这样有助于分辨必要的周全与对已完成事项反复打磨之间的区别。"},"career":{"h":"日常习惯变得停滞时","t":"熟悉的安排可以带来支持，也可能让人不假思索地照做。找一处自己已经不再检查或考虑其他做法的地方。你可以更新清单、调整任务顺序，或留出时间看看这个习惯是否仍然合适。"},"wealth":{"h":"综合提示","t":"星币骑士常让人留意日常付出如何一点点累积：履行承诺、核对细节，或重新回到手边的任务。重点不在速度，而在是否认真完成。在反思时，可以看看现有习惯是否仍服务于你的目标，以及哪里适合做一"},"next":"选一项经常要做的任务，写下其中最重要的两个细节。完成一次时把它们放在眼前，然后记下这套做法是否需要微调，或目前已经合用。"},{"n":76,"name":"星币王后","img":"Pents13.jpg","intro":"星币王后可以让你留意，关怀如何落实在日常生活中：一顿饭、一份预算、舒适的空间，或可靠的跟进。它不是要你承担所有事情，而是邀请你看看哪些付出能够持续、有哪些支持可用，以及自己的需要如何融入对他人的照顾。","love":{"h":"感情关系中","t":"留意关怀是否体现在双方看得见的行动里：谁会主动问候、说到做到，也为休息留出空间。如果大部分实际事务都由你承担，可以明确提出希望分担的一项任务，并确认彼此达成了什么约定，而不是只靠暗示。"},"study":{"h":"工作或学习中","t":"看看日常安排如何支撑你的进展。哪项任务、工具或习惯能让工作更容易处理？选一个本周可以试行的调整，并具体说清它需要多少时间或他人的帮助。"},"career":{"h":"抽到逆位时","t":"在答应新的请求前，先看看时间和精力都花在了哪里。你可以设定限度、请别人接手一项事务，或把一直拖延的基本需要排进日程。小幅调整也能让你的付出更可持续。"},"wealth":{"h":"综合提示","t":"星币王后可以让你留意，关怀如何落实在日常生活中：一顿饭、一份预算、舒适的空间，或可靠的跟进。它不是要你承担所有事情，而是邀请你看看哪些付出能够持续、有哪些支持可用，以及自己的需要如"},"next":"列两张简短清单：目前你把时间或精力花在哪些事上，以及什么能让你恢复状态。选一个能兼顾两者的小调整，例如分担一项任务，或留出半小时安静休息。"},{"n":77,"name":"星币国王","img":"Pents14.jpg","intro":"星币国王常与责任感、经验，以及愿意长期维护的事物相关。这张牌并不保证物质上的成功，而是可以帮助你看看：日常习惯是否体现了自己的价值观，你所依靠的生活安排是否仍服务于真正重要的目标。","love":{"h":"感情问题","t":"想想可靠在日常行动中是什么样子：遵守约定、留出相处时间、共同承担责任。留意双方是否都能感受到彼此的关心，并找出一件实际可谈的事，帮助你们了解彼此的期待。"},"study":{"h":"抽到逆位时","t":"留意外在形象或熟悉的做法，是否占用了太多注意力，以至于忽略了真正重要的事。写下自己在保护什么、为此付出了多少时间或精力，再想一个办法，把这些投入转向你希望践行的价值。"},"career":{"h":"工作或长期项目","t":"除了眼前的成果，也想想这份工作希望带来什么。检查时间安排、做事标准和合作方式是否支持这个目标。你可以调整一项习惯，或重新协商一项责任，让投入更能长久持续。"},"wealth":{"h":"综合提示","t":"星币国王常与责任感、经验，以及愿意长期维护的事物相关。这张牌并不保证物质上的成功，而是可以帮助你看看：日常习惯是否体现了自己的价值观，你所依靠的生活安排是否仍服务于真正重要的目标。"},"next":"写下一项对你重要的承诺，并在旁边记下它实际需要多少时间、精力或支持。本周选一个小调整，再留意它是否让这项承诺更可持续，也更有意义。"}];
